+
+    VBucketNodeLocator locator =
+        new VBucketNodeLocator(Arrays.asList(node1, node2, node3), config);
+    Collection<MemcachedNode> all = locator.getAll();
+
+    assertEquals(3, all.size());
+
+  }
+}

