+ * all copies or substantial portions of the Software.
+ *
+ * THE SOFTWARE IS PROVIDED "AS IS", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR
+ * IMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY,
+ * FITNESS FOR A PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE
+ * AUTHORS OR COPYRIGHT HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER
+ * LIABILITY, WHETHER IN AN ACTION OF CONTRACT, TORT OR OTHERWISE, ARISING
+ * FROM, OUT OF OR IN CONNECTION WITH THE SOFTWARE OR THE USE OR OTHER DEALING
+ * IN THE SOFTWARE.
+ */
+
+package com.couchbase.client;
+
+import com.couchbase.client.http.AsyncConnectionManager;
+import com.couchbase.client.http.AsyncConnectionRequest;
+import com.couchbase.client.http.RequestHandle;
+import com.couchbase.client.protocol.views.HttpOperation;
+
+import java.io.IOException;
+import java.io.InterruptedIOException;
+import java.net.InetSocketAddress;
+import java.util.ArrayList;
+import java.util.Collection;
+import java.util.concurrent.BlockingQueue;
+import java.util.concurrent.LinkedBlockingQueue;
+import java.util.concurrent.TimeUnit;
+
+import net.spy.memcached.compat.SpyObject;
+import net.spy.memcached.protocol.binary.BinaryMemcachedNodeImpl;
+
+import org.apache.http.HttpException;
+import org.apache.http.HttpRequest;
+import org.apache.http.HttpResponse;
+import org.apache.http.nio.NHttpClientConnection;
+import org.apache.http.nio.NHttpConnection;
+import org.apache.http.nio.entity.BufferingNHttpEntity;
+import org.apache.http.nio.entity.ConsumingNHttpEntity;
+import org.apache.http.nio.protocol.EventListener;
+import org.apache.http.nio.protocol.NHttpRequestExecutionHandler;
+import org.apache.http.nio.reactor.IOReactorException;
+import org.apache.http.nio.util.HeapByteBufferAllocator;
+import org.apache.http.protocol.HttpContext;
+
+/**
+ * Establishes a connection to a single Couchbase node.
+ *
+ * Based upon http://hc.apache.org/httpcomponents-core-ga/httpcore-nio/
+ * examples/org/apache/http/examples/nio/NHttpClientConnManagement.java
+ */
+public class ViewNode extends SpyObject {
+
+  private final InetSocketAddress addr;
+  private final AsyncConnectionManager connMgr;
+  private final long opQueueMaxBlockTime;
+  private final long defaultOpTimeout;
+  private final BlockingQueue<HttpOperation> writeQ;
+
+  public ViewNode(InetSocketAddress a, AsyncConnectionManager mgr,
+      LinkedBlockingQueue<HttpOperation> linkedBlockingQueue,
+      long maxBlockTime, long operationTimeout) {
+    addr = a;
+    connMgr = mgr;
+    writeQ = linkedBlockingQueue;
+    opQueueMaxBlockTime = maxBlockTime;
+    defaultOpTimeout = operationTimeout;
+  }
+
+  public void init() throws IOReactorException {
+    // Start the I/O reactor in a separate thread
+    Thread t = new Thread(new Runnable() {
+      public void run() {
+        try {
+          connMgr.execute();
+        } catch (InterruptedIOException ex) {
+          getLogger().error("I/O reactor Interrupted");
+        } catch (IOException e) {
+          getLogger().error("I/O error: " + e.getMessage());
+          e.printStackTrace();
+        }
+        getLogger().info("Couchbase I/O reactor terminated");
+      }
+    });
+    t.start();
+  }
+
+  public void doWrites() {
+    HttpOperation op;
+    while ((op = writeQ.poll()) != null) {
+      if (!op.isTimedOut() && !op.isCancelled()) {
+        AsyncConnectionRequest connRequest = connMgr.requestConnection();
+        try {
+          connRequest.waitFor();
+        } catch (InterruptedException e) {
+          getLogger().warn(
+              "Interrupted while trying to get a connection."
+                  + " Cancelling op");
+          op.cancel();
+          return;
+        }
+
+        NHttpClientConnection conn = connRequest.getConnection();
+        if (conn == null) {
+          getLogger().error("Failed to obtain connection. Cancelling op");
+          op.cancel();
+        } else {
+          HttpContext context = conn.getContext();
+          RequestHandle handle = new RequestHandle(connMgr, conn);
+          context.setAttribute("request-handle", handle);
+          context.setAttribute("operation", op);
+          conn.requestOutput();
+        }
+      }
+    }
+  }
+
+  public Collection<HttpOperation> destroyWriteQueue() {
+    Collection<HttpOperation> rv = new ArrayList<HttpOperation>();
+    writeQ.drainTo(rv);
+    return rv;
+  }
+
+  public boolean hasWriteOps() {
+    return !writeQ.isEmpty();
+  }
+
+  public void addOp(HttpOperation op) {
+    try {
+      if (!writeQ.offer(op, opQueueMaxBlockTime, TimeUnit.MILLISECONDS)) {
+        throw new IllegalStateException("Timed out waiting to add " + op
+            + "(max wait=" + opQueueMaxBlockTime + "ms)");
+      }
+    } catch (InterruptedException e) {
+      Thread.currentThread().interrupt();
+      throw new IllegalStateException("Interrupted while waiting to add " + op);
+    }
+  }
+
+  public InetSocketAddress getSocketAddress() {
+    return addr;
+  }
+
+  public void shutdown() throws IOException {
+    shutdown(0, TimeUnit.MILLISECONDS);
+  }
+
+  public void shutdown(long time, TimeUnit unit) throws IOException {
+    if (unit != TimeUnit.MILLISECONDS) {
+      connMgr.shutdown(TimeUnit.MILLISECONDS.convert(time, unit));
+    } else {
+      connMgr.shutdown(time);
+    }
+  }
+
+  static class MyHttpRequestExecutionHandler implements
+      NHttpRequestExecutionHandler {
+
+    public MyHttpRequestExecutionHandler() {
+      super();
+    }
+
+    public void initalizeContext(final HttpContext context,
+        final Object attachment) {
+    }
+
+    public void finalizeContext(final HttpContext context) {
+      RequestHandle handle =
+          (RequestHandle) context.removeAttribute("request-handle");
+      if (handle != null) {
+        handle.cancel();
+      }
+    }
+
+    public HttpRequest submitRequest(final HttpContext context) {
+      HttpOperation op = (HttpOperation) context.getAttribute("operation");
+      if (op == null) {
+        return null;
+      }
+      return op.getRequest();
+    }
+
+    public void handleResponse(final HttpResponse response,
+        final HttpContext context) {
+      RequestHandle handle =
+          (RequestHandle) context.removeAttribute("request-handle");
+      HttpOperation op = (HttpOperation) context.removeAttribute("operation");
+      if (handle != null) {
+        handle.completed();
+        op.handleResponse(response);
+      }
+    }
+
+    @Override
+    public ConsumingNHttpEntity responseEntity(HttpResponse response,
+        HttpContext context) throws IOException {
+      return new BufferingNHttpEntity(response.getEntity(),
+          new HeapByteBufferAllocator());
+    }
+  }
+
+  static class EventLogger extends SpyObject implements EventListener {
+
+    public void connectionOpen(final NHttpConnection conn) {
+      getLogger().debug("Connection open: " + conn);
+    }
+
+    public void connectionTimeout(final NHttpConnection conn) {
+      getLogger().error("Connection timed out: " + conn);
+    }
+
+    public void connectionClosed(final NHttpConnection conn) {
+      getLogger().debug("Connection closed: " + conn);
+    }
+
+    public void fatalIOException(final IOException ex,
+        final NHttpConnection conn) {
+      getLogger().error("I/O error: " + ex.getMessage());
+    }
+
+    public void fatalProtocolException(final HttpException ex,
+        final NHttpConnection conn) {
+      getLogger().error("HTTP error: " + ex.getMessage());
+    }
+  }
+}
diff --git a/src/main/java/com/couchbase/client/http/AsyncConnectionManager.java b/src/main/java/com/couchbase/client/http/AsyncConnectionManager.java
new file mode 100644
index 0000000000000000000000000000000000000000..1aea8ade54e3cd64b0c51192072d5bb902a144e1
--- /dev/null
+++ b/src/main/java/com/couchbase/client/http/AsyncConnectionManager.java
@@ -0,0 +1,285 @@
+/**
+ * Copyright (C) 2009-2011 Couchbase, Inc.
+ *
+ * Permission is hereby granted, free of charge, to any person obtaining a copy
+ * of this software and associated documentation files (the "Software"), to deal
+ * in the Software without restriction, including without limitation the rights
+ * to use, copy, modify, merge, publish, distribute, sublicense, and/or sell
+ * copies of the Software, and to permit persons to whom the Software is
+ * furnished to do so, subject to the following conditions:
+ *
+ * The above copyright notice and this permission notice shall be included in
+ * all copies or substantial portions of the Software.
+ *
+ * THE SOFTWARE IS PROVIDED "AS IS", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR
+ * IMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY,
+ * FITNESS FOR A PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE
+ * AUTHORS OR COPYRIGHT HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER
+ * LIABILITY, WHETHER IN AN ACTION OF CONTRACT, TORT OR OTHERWISE, ARISING
+ * FROM, OUT OF OR IN CONNECTION WITH THE SOFTWARE OR THE USE OR OTHER DEALING
+ * IN THE SOFTWARE.
+ */
+
+package com.couchbase.client.http;
+
+import java.io.IOException;
+import java.net.InetSocketAddress;
+import java.util.HashSet;
+import java.util.LinkedList;
+import java.util.Queue;
+import java.util.Set;
+
+import net.spy.memcached.compat.SpyObject;
+
+import org.apache.http.HttpException;
+import org.apache.http.HttpHost;
+import org.apache.http.impl.nio.DefaultClientIOEventDispatch;
+import org.apache.http.impl.nio.reactor.DefaultConnectingIOReactor;
+import org.apache.http.nio.ContentDecoder;
+import org.apache.http.nio.ContentEncoder;
+import org.apache.http.nio.NHttpClientConnection;
+import org.apache.http.nio.NHttpClientHandler;
+import org.apache.http.nio.reactor.ConnectingIOReactor;
+import org.apache.http.nio.reactor.IOEventDispatch;
+import org.apache.http.nio.reactor.IOReactorException;
+import org.apache.http.nio.reactor.SessionRequest;
+import org.apache.http.nio.reactor.SessionRequestCallback;
+import org.apache.http.params.HttpParams;
+
+/**
+ * An asynchronous HTTP connection manager.
+ */
+public class AsyncConnectionManager extends SpyObject {
+
+  private final HttpHost target;
+  private final int maxConnections;
+  private final NHttpClientHandler handler;
+  private final HttpParams params;
+  private final ConnectingIOReactor ioreactor;
+  private final Object lock;
+  private final Set<NHttpClientConnection> allConns;
+  private final Queue<NHttpClientConnection> availableConns;
+  private final Queue<AsyncConnectionRequest> pendingRequests;
+
+  private volatile boolean shutdown;
+
+  public AsyncConnectionManager(HttpHost target, int maxConnections,
+      NHttpClientHandler handler, HttpParams params) throws IOReactorException {
+    super();
+    this.target = target;
+    this.maxConnections = maxConnections;
+    this.handler = handler;
+    this.params = params;
+    this.lock = new Object();
+    this.allConns = new HashSet<NHttpClientConnection>();
+    this.availableConns = new LinkedList<NHttpClientConnection>();
+    this.pendingRequests = new LinkedList<AsyncConnectionRequest>();
+    this.ioreactor = new DefaultConnectingIOReactor(2, params);
+  }
+
+  public void execute() throws IOException {
+    IOEventDispatch dispatch =
+        new DefaultClientIOEventDispatch(new ManagedClientHandler(this.handler,
+            this), this.params);
+    this.ioreactor.execute(dispatch);
+  }
+
+  public void shutdown(long waitMs) throws IOException {
+    synchronized (this.lock) {
+      if (!this.shutdown) {
+        this.shutdown = true;
+        while (!this.pendingRequests.isEmpty()) {
+          AsyncConnectionRequest request = this.pendingRequests.remove();
+          request.cancel();
+        }
+        this.availableConns.clear();
+        this.allConns.clear();
+      }
+    }
+    this.ioreactor.shutdown(waitMs);
+  }
+
+  void addConnection(NHttpClientConnection conn) {
+    if (conn == null) {
+      return;
+    }
+    if (this.shutdown) {
+      return;
+    }
+    synchronized (this.lock) {
+      this.allConns.add(conn);
+    }
+  }
+
+  void removeConnection(NHttpClientConnection conn) {
+    if (conn == null) {
+      return;
+    }
+    if (this.shutdown) {
+      return;
+    }
+    synchronized (this.lock) {
+      if (this.allConns.remove(conn)) {
+        this.availableConns.remove(conn);
+      }
+      processConnectionRequests();
+    }
+  }
+
+  public AsyncConnectionRequest requestConnection() {
+    if (this.shutdown) {
+      throw new IllegalStateException("Connection manager has been shut down");
+    }
+    AsyncConnectionRequest request = new AsyncConnectionRequest();
+    synchronized (this.lock) {
+      while (!this.availableConns.isEmpty()) {
+        NHttpClientConnection conn = this.availableConns.remove();
+        if (conn.isOpen()) {
+          getLogger().debug("Re-using persistent connection");
+          request.setConnection(conn);
+          break;
+        } else {
+          this.allConns.remove(conn);
+        }
+      }
+      if (!request.isCompleted()) {
+        this.pendingRequests.add(request);
+        processConnectionRequests();
+      }
+    }
+    return request;
+  }
+
+  public void releaseConnection(NHttpClientConnection conn) {
+    if (conn == null) {
+      return;
+    }
+    if (this.shutdown) {
+      return;
+    }
+    synchronized (this.lock) {
+      if (this.allConns.contains(conn)) {
+        if (conn.isOpen()) {
+          conn.setSocketTimeout(0);
+          AsyncConnectionRequest request = this.pendingRequests.poll();
+          if (request != null) {
+            getLogger().debug("Re-using persistent connection");
+            request.setConnection(conn);
+          } else {
+            this.availableConns.add(conn);
+          }
+        } else {
+          this.allConns.remove(conn);
+          processConnectionRequests();
+        }
+      }
+    }
+  }
+
+  private void processConnectionRequests() {
+    while (this.allConns.size() < this.maxConnections) {
+      AsyncConnectionRequest request = this.pendingRequests.poll();
+      if (request == null) {
+        break;
+      }
+      InetSocketAddress address =
+          new InetSocketAddress(this.target.getHostName(),
+          this.target.getPort());
+      ConnRequestCallback callback = new ConnRequestCallback(request);
+      getLogger().info("Opening new CouchDB connection");
+      this.ioreactor.connect(address, null, request, callback);
+    }
+  }
+
+  static class ManagedClientHandler implements NHttpClientHandler {
+
+    private final NHttpClientHandler handler;
+    private final AsyncConnectionManager connMgr;
+
+    public ManagedClientHandler(NHttpClientHandler handler,
+        AsyncConnectionManager connMgr) {
+      super();
+      this.handler = handler;
+      this.connMgr = connMgr;
+    }
+
+    public void connected(NHttpClientConnection conn, Object attachment) {
+      AsyncConnectionRequest request = (AsyncConnectionRequest) attachment;
+      this.handler.connected(conn, attachment);
+      this.connMgr.addConnection(conn);
+      request.setConnection(conn);
+    }
+
+    public void closed(NHttpClientConnection conn) {
+      this.connMgr.removeConnection(conn);
+      this.handler.closed(conn);
+    }
+
+    public void requestReady(NHttpClientConnection conn) {
+      this.handler.requestReady(conn);
+    }
+
+    public void outputReady(NHttpClientConnection conn,
+        ContentEncoder encoder) {
+      this.handler.outputReady(conn, encoder);
+    }
+
+    public void responseReceived(NHttpClientConnection conn) {
+      this.handler.responseReceived(conn);
+    }
+
+    public void inputReady(NHttpClientConnection conn, ContentDecoder decoder) {
+      this.handler.inputReady(conn, decoder);
+    }
+
+    public void exception(NHttpClientConnection conn, HttpException ex) {
+      this.handler.exception(conn, ex);
+    }
+
+    public void exception(NHttpClientConnection conn, IOException ex) {
+      this.handler.exception(conn, ex);
+    }
+
+    public void timeout(NHttpClientConnection conn) {
+      this.handler.timeout(conn);
+    }
+  }
+
+  static class ConnRequestCallback extends SpyObject implements
+      SessionRequestCallback {
+
+    private final AsyncConnectionRequest connRequest;
+
+    public ConnRequestCallback(AsyncConnectionRequest request) {
+      super();
+      connRequest = request;
+    }
+
+    public void completed(SessionRequest request) {
+      getLogger().info(request.getRemoteAddress()
+          + " - Session request successful");
+    }
+
+    public void cancelled(SessionRequest request) {
+      getLogger().info(request.getRemoteAddress()
+          + " - Session request cancelled");
+      connRequest.cancel();
+    }
+
+    public void failed(SessionRequest request) {
+      getLogger().error(request.getRemoteAddress()
+          + " - Session request failed");
+      IOException ex = request.getException();
+      if (ex != null) {
+        ex.printStackTrace();
+      }
+      connRequest.cancel();
+    }
+
+    public void timeout(SessionRequest request) {
+      getLogger().info(request.getRemoteAddress()
+          + " - Session request timed out");
+      connRequest.cancel();
+    }
+  }
+}
diff --git a/src/main/java/com/couchbase/client/http/AsyncConnectionRequest.java b/src/main/java/com/couchbase/client/http/AsyncConnectionRequest.java
new file mode 100644
index 0000000000000000000000000000000000000000..2284879b47f0fc2176ce8186f978ce53aa8a184d
--- /dev/null
+++ b/src/main/java/com/couchbase/client/http/AsyncConnectionRequest.java
@@ -0,0 +1,78 @@
+/**
+ * Copyright (C) 2009-2011 Couchbase, Inc.
+ *
+ * Permission is hereby granted, free of charge, to any person obtaining a copy
+ * of this software and associated documentation files (the "Software"), to deal
+ * in the Software without restriction, including without limitation the rights
+ * to use, copy, modify, merge, publish, distribute, sublicense, and/or sell
+ * copies of the Software, and to permit persons to whom the Software is
+ * furnished to do so, subject to the following conditions:
+ *
+ * The above copyright notice and this permission notice shall be included in
+ * all copies or substantial portions of the Software.
+ *
+ * THE SOFTWARE IS PROVIDED "AS IS", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR
+ * IMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY,
+ * FITNESS FOR A PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE
+ * AUTHORS OR COPYRIGHT HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER
+ * LIABILITY, WHETHER IN AN ACTION OF CONTRACT, TORT OR OTHERWISE, ARISING
+ * FROM, OUT OF OR IN CONNECTION WITH THE SOFTWARE OR THE USE OR OTHER DEALING
+ * IN THE SOFTWARE.
+ */
+
+package com.couchbase.client.http;
+
+import org.apache.http.nio.NHttpClientConnection;
+
+/**
+ * An AsyncConnectionRequest.
+ */
+public class AsyncConnectionRequest {
+
+  private volatile boolean completed;
+  private volatile NHttpClientConnection conn;
+
+  public AsyncConnectionRequest() {
+    super();
+  }
+
+  public boolean isCompleted() {
+    return this.completed;
+  }
+
+  public void setConnection(NHttpClientConnection newConn) {
+    if (this.completed) {
+      return;
+    }
+    this.completed = true;
+    synchronized (this) {
+      this.conn = newConn;
+      notifyAll();
+    }
+  }
+
+  public NHttpClientConnection getConnection() {
+    return this.conn;
+  }
+
+  public void cancel() {
+    if (this.completed) {
+      return;
+    }
+    this.completed = true;
+    synchronized (this) {
+      notifyAll();
+    }
+  }
+
+  public void waitFor() throws InterruptedException {
+    if (this.completed) {
+      return;
+    }
+    synchronized (this) {
+      while (!this.completed) {
+        wait();
+      }
+    }
+  }
+}
