+ * IN THE SOFTWARE.
+ */
+
+package com.couchbase.client.protocol.views;
+
+import net.spy.memcached.ops.OperationCallback;
+
+/**
+ * An operation that represents a view that calls the map
+ * function and excludes the documents in the result.
+ */
