+    void gotData(ViewResponse response);
+  }
+}
diff --git a/src/main/java/com/couchbase/client/protocol/views/NoDocsOperationImpl.java b/src/main/java/com/couchbase/client/protocol/views/NoDocsOperationImpl.java
new file mode 100644
index 0000000000000000000000000000000000000000..56ce28a808e64e08014740a9f3763aeb352e21b8
--- /dev/null
+++ b/src/main/java/com/couchbase/client/protocol/views/NoDocsOperationImpl.java
@@ -0,0 +1,76 @@
+/**
+ * Copyright (C) 2009-2011 Couchbase, Inc.
+ *
+ * Permission is hereby granted, free of charge, to any person obtaining a copy
+ * of this software and associated documentation files (the "Software"), to deal
+ * in the Software without restriction, including without limitation the rights
+ * to use, copy, modify, merge, publish, distribute, sublicense, and/or sell
+ * copies of the Software, and to permit persons to whom the Software is
+ * furnished to do so, subject to the following conditions:
+ *
+ * The above copyright notice and this permission notice shall be included in
+ * all copies or substantial portions of the Software.
+ *
+ * THE SOFTWARE IS PROVIDED "AS IS", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR
+ * IMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY,
+ * FITNESS FOR A PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE
+ * AUTHORS OR COPYRIGHT HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER
+ * LIABILITY, WHETHER IN AN ACTION OF CONTRACT, TORT OR OTHERWISE, ARISING
+ * FROM, OUT OF OR IN CONNECTION WITH THE SOFTWARE OR THE USE OR OTHER DEALING
+ * IN THE SOFTWARE.
+ */
+
+package com.couchbase.client.protocol.views;
+
+import java.text.ParseException;
+import java.util.Collection;
+import java.util.LinkedList;
+
+import org.apache.http.HttpRequest;
+import org.codehaus.jettison.json.JSONArray;
+import org.codehaus.jettison.json.JSONException;
+import org.codehaus.jettison.json.JSONObject;
+
+/**
+ * Implementation of a view that calls the map
+ * function and excludes the documents in the result.
+ */
+public class NoDocsOperationImpl extends ViewOperationImpl{
+
+  public NoDocsOperationImpl(HttpRequest r, ViewCallback cb) {
+    super(r, cb);
+  }
+
+  protected ViewResponseNoDocs parseResult(String json)
+    throws ParseException {
+    final Collection<ViewRow> rows = new LinkedList<ViewRow>();
+    final Collection<RowError> errors = new LinkedList<RowError>();
+    if (json != null) {
+      try {
+        JSONObject base = new JSONObject(json);
+        if (base.has("rows")) {
+          JSONArray ids = base.getJSONArray("rows");
+          for (int i = 0; i < ids.length(); i++) {
+            JSONObject elem = ids.getJSONObject(i);
+            String id = elem.getString("id");
+            String key = elem.getString("key");
+            String value = elem.getString("value");
+            rows.add(new ViewRowNoDocs(id, key, value));
+          }
+        }
+        if (base.has("errors")) {
+          JSONArray ids = base.getJSONArray("errors");
+          for (int i = 0; i < ids.length(); i++) {
+            JSONObject elem = ids.getJSONObject(i);
+            String from = elem.getString("from");
+            String reason = elem.getString("reason");
+            errors.add(new RowError(from, reason));
+          }
+        }
+      } catch (JSONException e) {
+        throw new ParseException("Cannot read json: " + json, 0);
+      }
+    }
+    return new ViewResponseNoDocs(rows, errors);
+  }
+}
diff --git a/src/main/java/com/couchbase/client/protocol/views/Paginator.java b/src/main/java/com/couchbase/client/protocol/views/Paginator.java
new file mode 100644
index 0000000000000000000000000000000000000000..fc8130617ce989c7a479e2dabbef16a735b64d2f
--- /dev/null
+++ b/src/main/java/com/couchbase/client/protocol/views/Paginator.java
@@ -0,0 +1,97 @@
+/**
+ * Copyright (C) 2009-2011 Couchbase, Inc.
+ *
+ * Permission is hereby granted, free of charge, to any person obtaining a copy
+ * of this software and associated documentation files (the "Software"), to deal
+ * in the Software without restriction, including without limitation the rights
+ * to use, copy, modify, merge, publish, distribute, sublicense, and/or sell
+ * copies of the Software, and to permit persons to whom the Software is
+ * furnished to do so, subject to the following conditions:
+ *
+ * The above copyright notice and this permission notice shall be included in
+ * all copies or substantial portions of the Software.
+ *
+ * THE SOFTWARE IS PROVIDED "AS IS", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR
+ * IMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY,
+ * FITNESS FOR A PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE
+ * AUTHORS OR COPYRIGHT HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER
+ * LIABILITY, WHETHER IN AN ACTION OF CONTRACT, TORT OR OTHERWISE, ARISING
+ * FROM, OUT OF OR IN CONNECTION WITH THE SOFTWARE OR THE USE OR OTHER DEALING
+ * IN THE SOFTWARE.
+ */
+
+package com.couchbase.client.protocol.views;
+
+import com.couchbase.client.CouchbaseClient;
+import com.couchbase.client.internal.HttpFuture;
+
+import java.util.Iterator;
+
+import net.spy.memcached.compat.SpyObject;
+
+/**
+ * A Paginator.
+ */
+public class Paginator extends SpyObject
+  implements Iterator<ViewRow> {
+
+  private static final int MIN_RESULTS = 15;
+
+  private final CouchbaseClient client;
+  private final Query query;
+  private final View view;
+  private final int docsPerPage;
+
+  private ViewResponse page;
+  private Iterator<ViewRow> pageItr;
+  private ViewRow lastRow;
+  private int rowsIterated;
+
+  public Paginator(CouchbaseClient client, View view, Query query,
+      int numDocs) {
+    this.client = client;
+    this.view = view;
+    this.query = query.copy();
+    this.docsPerPage = (MIN_RESULTS > numDocs) ? MIN_RESULTS : numDocs;
+    getNextPage(this.query.setLimit(docsPerPage + 1));
+  }
+
+  @Override
+  public boolean hasNext() {
+    if (!pageItr.hasNext() && page.size() < docsPerPage) {
+      return false;
+    } else if (!(rowsIterated < docsPerPage)) {
+      lastRow = pageItr.next();
+      query.setStartkeyDocID(lastRow.getId());
+      query.setRangeStart(lastRow.getKey());
+      getNextPage(query);
+    }
+    return true;
+  }
+
+  @Override
+  public ViewRow next() {
+    if (rowsIterated <= docsPerPage) {
+      rowsIterated++;
+      lastRow = pageItr.next();
+      return lastRow;
+    }
+    return null;
+  }
+
+  @Override
+  public void remove() {
+    throw new UnsupportedOperationException("Remove is unsupported");
+  }
+
+  private HttpFuture<ViewResponse> getNextPage(Query q) {
+    if (query.willReduce()) {
+      throw new RuntimeException("Pagination is not supported for reduced"
+          + " views");
+    }
+    page = client.query(view, q);
+    pageItr = page.iterator();
+    rowsIterated = 0;
+    return null;
+  }
+}
diff --git a/src/main/java/com/couchbase/client/protocol/views/Query.java b/src/main/java/com/couchbase/client/protocol/views/Query.java
new file mode 100644
index 0000000000000000000000000000000000000000..bd300742467f6a32ac4ec6547e81e85f1ef88786
--- /dev/null
+++ b/src/main/java/com/couchbase/client/protocol/views/Query.java
@@ -0,0 +1,231 @@
+/**
+ * Copyright (C) 2009-2011 Couchbase, Inc.
+ *
+ * Permission is hereby granted, free of charge, to any person obtaining a copy
+ * of this software and associated documentation files (the "Software"), to deal
+ * in the Software without restriction, including without limitation the rights
+ * to use, copy, modify, merge, publish, distribute, sublicense, and/or sell
+ * copies of the Software, and to permit persons to whom the Software is
+ * furnished to do so, subject to the following conditions:
+ *
+ * The above copyright notice and this permission notice shall be included in
+ * all copies or substantial portions of the Software.
+ *
+ * THE SOFTWARE IS PROVIDED "AS IS", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR
+ * IMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY,
+ * FITNESS FOR A PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE
+ * AUTHORS OR COPYRIGHT HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER
+ * LIABILITY, WHETHER IN AN ACTION OF CONTRACT, TORT OR OTHERWISE, ARISING
+ * FROM, OUT OF OR IN CONNECTION WITH THE SOFTWARE OR THE USE OR OTHER DEALING
+ * IN THE SOFTWARE.
+ */
+
+package com.couchbase.client.protocol.views;
+
+import java.util.HashMap;
+import java.util.Map;
+import java.util.Map.Entry;
+
+import net.spy.memcached.util.StringUtils;
+
+/**
+ * A Query.
+ */
+public class Query {
+  private static final String DESCENDING = "descending";
+  private static final String ENDKEY = "endkey";
+  private static final String ENDKEYDOCID = "endkey_docid";
+  private static final String GROUP = "group";
+  private static final String GROUPLEVEL = "group_level";
+  private static final String INCLUSIVEEND = "inclusive_end";
+  private static final String KEY = "key";
+  private static final String LIMIT = "limit";
+  private static final String REDUCE = "reduce";
+  private static final String SKIP = "skip";
+  private static final String STALE = "stale";
+  private static final String STARTKEY = "startkey";
+  private static final String STARTKEYDOCID = "startkey_docid";
+  private static final String UPDATESEQ = "update_seq";
+  private boolean includedocs = false;
+
+  private Map<String, Object> args;
+
+  public Query() {
+    args = new HashMap<String, Object>();
+  }
+
+  public boolean willReduce() {
+    return (args.containsKey(REDUCE))
+      ? ((Boolean)args.get(REDUCE)).booleanValue() : false;
+  }
+
+  public boolean willIncludeDocs() {
+    return includedocs;
+  }
+
+  public Query setDescending(boolean descending) {
+    args.put(DESCENDING, Boolean.valueOf(descending));
+    return this;
+  }
+
+  public Query setEndkeyDocID(String endkeydocid) {
+    args.put(ENDKEYDOCID, endkeydocid);
+    return this;
+  }
+
+  public Query setGroup(boolean group) {
+    args.put(GROUP, Boolean.valueOf(group));
+    return this;
+  }
+
+  public Query setGroup(boolean group, int grouplevel) {
+    args.put(GROUP, new Boolean(group));
+    args.put(GROUPLEVEL, Integer.valueOf((grouplevel)));
+    return this;
+  }
+
+  public Query setIncludeDocs(boolean include) {
+    this.includedocs = include;
+    return this;
+  }
+
+  public Query setInclusiveEnd(boolean inclusiveend) {
+    args.put(INCLUSIVEEND, Boolean.valueOf(inclusiveend));
+    return this;
+  }
+
+  public Query setKey(String key) {
+    args.put(KEY, key);
+    return this;
+  }
+
+  public Query setLimit(int limit) {
+    args.put(LIMIT, Integer.valueOf(limit));
+    return this;
+  }
+
+  public Query setRange(String startkey, String endkey) {
+    args.put(ENDKEY, endkey);
+    args.put(STARTKEY, startkey);
+    return this;
+  }
+
+  public Query setRangeStart(String startkey) {
+    args.put(STARTKEY, startkey);
+    return this;
+  }
+
+  public Query setReduce(boolean reduce) {
+    args.put(REDUCE, new Boolean(reduce));
+    return this;
+  }
+
+  public Query setRangeEnd(String endkey) {
+    args.put(ENDKEY, endkey);
+    return this;
+  }
+
+  public Query setSkip(int docstoskip) {
+    args.put(SKIP, Integer.valueOf(docstoskip));
+    return this;
+  }
+
+  public Query setStale(Stale stale) {
+    if (stale == Stale.OK) {
+      args.put(STALE, stale);
+    } else if (stale == Stale.UPDATE_AFTER) {
+      args.put(STALE, stale);
+    }
+    return this;
+  }
+
+  public Query setStartkeyDocID(String startkeydocid) {
+    args.put(STARTKEYDOCID, startkeydocid);
+    return this;
+  }
+
+  public Query setUpdateSeq(boolean updateseq) {
+    args.put(UPDATESEQ, Boolean.toString(updateseq));
+    return this;
+  }
+
+  public Query copy() {
+    Query query = new Query();
+
+    if (args.containsKey(DESCENDING)) {
+      query.setDescending(((Boolean)args.get(DESCENDING)).booleanValue());
+    }
+    if (args.containsKey(ENDKEY)) {
+      query.setRangeEnd(((String)args.get(ENDKEY)));
+    }
+    if (args.containsKey(ENDKEYDOCID)) {
+      query.setEndkeyDocID(((String)args.get(ENDKEYDOCID)));
+    }
+    if (args.containsKey(GROUP)) {
+      query.setGroup(((Boolean)args.get(GROUP)).booleanValue());
+    }
+    if (args.containsKey(GROUPLEVEL)) {
+      query.setGroup(((Boolean)args.get(GROUP)).booleanValue(),
+          ((Integer)args.get(GROUPLEVEL)).intValue());
+    }
+    if (args.containsKey(INCLUSIVEEND)) {
+      query.setInclusiveEnd(((Boolean)args.get(INCLUSIVEEND)).booleanValue());
+    }
+    if (args.containsKey(KEY)) {
+      query.setEndkeyDocID(((String)args.get(KEY)));
+    }
+    if (args.containsKey(LIMIT)) {
+      query.setLimit(((Integer)args.get(LIMIT)).intValue());
+    }
+    if (args.containsKey(REDUCE)) {
+      query.setReduce(((Boolean)args.get(REDUCE)).booleanValue());
+    }
+    if (args.containsKey(SKIP)) {
+      query.setSkip(((Integer)args.get(SKIP)).intValue());
+    }
+    if (args.containsKey(STALE)) {
+      query.setStale(((Stale)args.get(STALE)));
+    }
+    if (args.containsKey(STARTKEY)) {
+      query.setRangeStart(((String)args.get(STARTKEY)));
+    }
+    if (args.containsKey(STARTKEYDOCID)) {
+      query.setStartkeyDocID(((String)args.get(STARTKEYDOCID)));
+    }
+    if (args.containsKey(UPDATESEQ)) {
+      query.setUpdateSeq(((Boolean)args.get(UPDATESEQ)).booleanValue());
+    }
+    setIncludeDocs(willIncludeDocs());
+
+    return query;
+  }
+
+  @Override
+  public String toString() {
+    boolean first = true;
+    StringBuffer result = new StringBuffer();
+    for (Entry<String, Object> arg : args.entrySet()) {
+      if (first) {
+        result.append("?");
+        first = false;
+      } else {
+        result.append("&");
+      }
+      result.append(getArg(arg.getKey(), arg.getValue()));
+    }
+    return result.toString();
+  }
+
+  private String getArg(String key, Object value) {
+    // Special case
+    if (key.equals(STARTKEYDOCID)) {
+      return key + "=" + value;
+    } else if (value instanceof Stale) {
+      return key + "=" + ((Stale) value).toString();
+    } else if (StringUtils.isJsonObject(value.toString())) {
+      return key + "=" + value.toString();
+    } else {
+      return key + "=\"" + value + "\"";
+    }
+  }
+}
