+    // Shut down, null things out. Error tests have
+    // unpredictable timing issues.  See test from Spymemcached
+    // net.spy.memcached.ClientBaseCase
+    client.shutdown(200, TimeUnit.MILLISECONDS);
+    client = null;
+    System.gc();
+  }
 }
