+/**
+ * A callack to requeue a http operation.
+ */
+public class RequeueOpCallback {
+
+  private final ViewConnection conn;
+
+  public RequeueOpCallback(ViewConnection vc) {
+    conn = vc;
+  }
+
+  public void invoke(HttpOperation op) {
+    conn.addOp(op);
+  }
