+  }
+
+  public InvalidViewException(String message) {
+    super(message);
+  }
+
+  public InvalidViewException(String message, Throwable cause) {
+    super(message, cause);
+  }
+
+  public InvalidViewException(Throwable cause) {
+    super(cause);
+  }
+}
