+    pw.println("  <!-- CouchbaseClient three arguments. "
+            + "URL list, bucket name and bucket password. -->");
+    pw.println("            <constructor-arg>");
+    pw.println("                <list>");
+    pw.println("                    <bean id=\"url1\" "
