+          val =
+              tcService.decode(tc, new CachedData(flags, data, tc.getMaxSize()));
+        }
+
+        public void complete() {
+          latch.countDown();
+        }
+      });
+      rv.setOperation(op);
+      mconn.enqueueOperation(key, op);
+      futures.add(rv);
+    }
+
+    return new ReplicaGetFuture<T>(operationTimeout, futures);
+  }
