+    manager.createNamedBucket(BucketType.COUCHBASE,BUCKET, 100, 0, "", true);
+    Thread.sleep(1000);
+    manager.updateBucket(BUCKET, 200, AuthType.SASL, 0, 11212, "", true);
+  }
+
