+  /**
+   * Lists the currently serviceable {@link HttpHost}s for verification
+   * purposes.
+   *
+   * @return a list of currently serviceable {@link HttpHost}s.
+   */
+  List<HttpHost> getConnectedHosts() {
+    return viewNodes;
+  }
+
 }
