-    shuttingDown = true;
-    long waittime = time;
-    if (unit != TimeUnit.MILLISECONDS) {
-      waittime = TimeUnit.MILLISECONDS.convert(time, unit);
-    }
-
-    connMgr.shutdown(waittime);
-    try {
