diff --git a/src/test/java/com/couchbase/client/CCCPAwarenessTest.java b/src/test/java/com/couchbase/client/CCCPAwarenessTest.java
new file mode 100644
index 0000000000000000000000000000000000000000..68d3973ff8902b40dc8d666780499ee3a2c27c75
--- /dev/null
+++ b/src/test/java/com/couchbase/client/CCCPAwarenessTest.java
@@ -0,0 +1,189 @@
+/**
+ * Copyright (C) 2009-2013 Couchbase, Inc.
+ *
+ * Permission is hereby granted, free of charge, to any person obtaining a copy
+ * of this software and associated documentation files (the "Software"), to deal
+ * in the Software without restriction, including without limitation the rights
