diff --git a/src/test/java/com/couchbase/client/vbucket/provider/BucketConfigurationProviderTest.java b/src/test/java/com/couchbase/client/vbucket/provider/BucketConfigurationProviderTest.java
new file mode 100644
index 0000000000000000000000000000000000000000..adb45b0bfbc747c369ded6de081a359ccf466701
--- /dev/null
+++ b/src/test/java/com/couchbase/client/vbucket/provider/BucketConfigurationProviderTest.java
@@ -0,0 +1,237 @@
+/**
+ * Copyright (C) 2009-2013 Couchbase, Inc.
+ *
+ * Permission is hereby granted, free of charge, to any person obtaining a copy
+ * of this software and associated documentation files (the "Software"), to deal
+ * in the Software without restriction, including without limitation the rights
