-    }
-    synchronized (this) {
-      while (!this.completed) {
-        wait(5000);
-        this.completed = true;
-      }
-    }
-  }
-}
diff --git a/src/main/java/com/couchbase/client/http/HttpResponseCallback.java b/src/main/java/com/couchbase/client/http/HttpResponseCallback.java
