index 0000000000000000000000000000000000000000..9092f670ead5c03ee4ba475b1695d64a8d9f0eec
--- /dev/null
+++ b/src/main/java/com/couchbase/client/BootstrapNodeUtil.java
@@ -0,0 +1,158 @@
+/**
