diff --git a/src/test/java/net/spy/memcached/auth/AuthTest.java b/src/test/java/net/spy/memcached/auth/AuthTest.java
new file mode 100644
index 0000000000000000000000000000000000000000..3e2d313ab8e235e6fb71a8cb4fd585ca120fa836
--- /dev/null
+++ b/src/test/java/net/spy/memcached/auth/AuthTest.java
@@ -0,0 +1,181 @@
+/**
