index 0000000000000000000000000000000000000000..1a14ec162015df8bd5863bc6afb171371348c90a
--- /dev/null
+++ b/src/main/java/com/couchbase/client/vbucket/provider/BucketConfigurationProvider.java
@@ -0,0 +1,509 @@
+/**
