+    public void run() {
+      String threadNameBase = "Couchbase/Resubscriber (Status: ";
+      Thread.currentThread().setName(threadNameBase + "running)");
+      LOGGER.log(Level.CONFIG, "Resubscribing for {0} using base list {1}",
