+
+    int tries = 100;
+    for(int i = 0; i < tries; i++) {
+      connFact.updateStoredBaseList(connFact.getVBucketConfig());
+      assertTrue(providerMock.baseListUpdated);
+      List<URI> newList = connFact.getStoredBaseList();
