new file mode 100644
index 0000000000000000000000000000000000000000..fee66fb972730c45c5a18297a612c6b4e17f26c3
--- /dev/null
+++ b/src/main/java/com/couchbase/client/http/HttpResponseCallback.java
@@ -0,0 +1,223 @@
+/**
