+      ArrayList<MemcachedNode> nodes =
+        new ArrayList<MemcachedNode>(getLocator().getAll());
+      if (nodes.size() > 0) {
+        InetSocketAddress addr = (InetSocketAddress) nodes.get(0)
+          .getSocketAddress();
+        return original.replaceAll("\\$HOST", addr.getHostName());
+      } else {
