-  public ViewNode(InetSocketAddress a, AsyncConnectionManager mgr,
-      long queueLen, long maxBlockTime, long operationTimeout, String usr,
-      String pwd) {
-    addr = a;
-    connMgr = mgr;
-    opQueueMaxBlockTime = maxBlockTime;
