-      public void run() {
-        try {
-          connMgr.execute();
-        } catch (InterruptedIOException ex) {
-          getLogger().error("I/O reactor Interrupted", ex);
-        } catch (IOException e) {
-          getLogger().error("I/O error: " + e.getMessage(), e);
-        }
