@@ -0,0 +1,97 @@
+package com.couchbase.client.java.document.json;
+
+import java.util.ArrayList;
+import java.util.List;
+
+public class JsonArray implements JsonValue {
+
+  private final List<Object> content;
+
+  private JsonArray() {
+    content = new ArrayList<Object>();
+  }
+
+  public static JsonArray empty() {
+    return new JsonArray();
+  }
+
+  public Object get(int index) {
+    return content.get(index);
+  }
+
+  public JsonArray add(String value) {
+    content.add(value);
+    return this;
+  }
+
+  public String getString(int index) {
+    return (String) content.get(index);
+  }
+
+  public JsonArray add(long value) {
+    content.add(value);
+    return this;
+  }
+
+  public long getLong(int index) {
+    return (Long) content.get(index);
+  }
+
+  public JsonArray add(int value) {
+    content.add(value);
+    return this;
+  }
+
+  public int getInt(int index) {
+    return (Integer) content.get(index);
+  }
+
+  public JsonArray add(double value) {
+    content.add(value);
+    return this;
+  }
+
+  public double getDouble(int index) {
+    return (Double) content.get(index);
+  }
+
+  public JsonArray add(boolean value) {
+    content.add(value);
+    return this;
+  }
+
+  public boolean getBoolean(int index) {
+    return (Boolean) content.get(index);
+  }
+
+  public JsonArray add(JsonObject value) {
+    content.add(value);
+    return this;
+  }
+
+  public JsonObject getObject(int index) {
+    return (JsonObject) content.get(index);
+  }
+
+  public JsonArray add(JsonArray value) {
+    content.add(value);
+    return this;
+  }
+
+  public JsonArray getArray(int index) {
+    return (JsonArray) content.get(index);
+  }
+
+  public List<Object> toList() {
+    return content;
+  }
+
+  public boolean isEmpty() {
+    return content.isEmpty();
+  }
+
+  public int size() {
+    return content.size();
+  }
+
+}
diff --git a/src/main/java/com/couchbase/client/java/document/json/JsonObject.java b/src/main/java/com/couchbase/client/java/document/json/JsonObject.java
new file mode 100644
index 0000000000000000000000000000000000000000..2cda542e95d17c0f0468ac46c79ac16b14e721c5
--- /dev/null
+++ b/src/main/java/com/couchbase/client/java/document/json/JsonObject.java
@@ -0,0 +1,116 @@
+package com.couchbase.client.java.document.json;
+
+import java.util.HashMap;
+import java.util.Map;
+import java.util.Set;
+
+/**
+ * Represents a JSON Object, which acts very much like a java Map, but is limited
+ * encode the types supported in JSON.
+ */
+public class JsonObject implements JsonValue {
+
+  /**
+   * The map which backs the object itself.
+   */
+  private final Map<String, Object> content;
+
+  /**
+   * Creates a new {@link JsonObject}.
+   */
+  private JsonObject() {
+    content = new HashMap<String, Object>();
+  }
+
+  /**
+   * Factory method encode empty a new and empty {@link JsonObject}.
+   * @return a new {@link JsonObject}.
+   */
+  public static JsonObject empty() {
+    return new JsonObject();
+  }
+
+  public Object get(String name) {
+    return content.get(name);
+  }
+
+  public JsonObject put(String name, String value) {
+    content.put(name, value);
+    return this;
+  }
+
+  public String getString(String name) {
+    return (String) content.get(name);
+  }
+
+  public JsonObject put(String name, int value) {
+    content.put(name, value);
+    return this;
+  }
+
+  public int getInt(String name) {
+    return (Integer) content.get(name);
+  }
+
+  public JsonObject put(String name, long value) {
+    content.put(name, value);
+    return this;
+  }
+
+  public long getLong(String name) {
+    return (Long) content.get(name);
+  }
+
+  public JsonObject put(String name, double value) {
+    content.put(name, value);
+    return this;
+  }
+
+  public double getDouble(String name) {
+    return (Double) content.get(name);
+  }
+
+  public JsonObject put(String name, boolean value) {
+    content.put(name, value);
+    return this;
+  }
+
+  public boolean getBoolean(String name) {
+    return (Boolean) content.get(name);
+  }
+
+  public JsonObject put(String name, JsonObject value) {
+    content.put(name, value);
+    return this;
+  }
+
+  public JsonObject getObject(String name) {
+    return (JsonObject) content.get(name);
+  }
+
+  public JsonObject put(String name, JsonArray value) {
+    content.put(name, value);
+    return this;
+  }
+
+  public JsonArray getArray(String name) {
+    return (JsonArray) content.get(name);
+  }
+
+  public Set<String> getNames() {
+    return content.keySet();
+  }
+
+  public boolean isEmpty() {
+    return content.isEmpty();
+  }
+
+  public Map<String, Object> toMap() {
+    return content;
+  }
+
+  public int size() {
+    return content.size();
+  }
+
+}
