diff --git a/src/main/java/com/couchbase/client/java/document/json/JsonObject.java b/src/main/java/com/couchbase/client/java/document/json/JsonObject.java
index d6a9a0b79e154fce67dd45af4ca2744e142b4e86..14c50a6ee0efd6883a69f593ad48687857bbdab0 100644
--- a/src/main/java/com/couchbase/client/java/document/json/JsonObject.java
+++ b/src/main/java/com/couchbase/client/java/document/json/JsonObject.java
@@ -115,6 +115,21 @@ public class JsonObject implements JsonValue {

     @Override
     public String toString() {
-        return content.toString();
+        StringBuilder sb = new StringBuilder("{");
+        int size = content.size();
+        int item = 0;
+        for(Map.Entry<String, Object> entry : content.entrySet()) {
+            sb.append("\"").append(entry.getKey()).append("\":");
+            if (entry.getValue() instanceof String) {
+                sb.append("\"").append(entry.getValue()).append("\"");
+            } else {
+                sb.append(entry.getValue().toString());
+            }
+            if (++item < size) {
+                sb.append(",");
+            }
+        }
+        sb.append("}");
+        return sb.toString();
     }
 }
