diff --git a/src/integration/java/com/couchbase/client/java/BinaryBinaryDocumentTest.java b/src/integration/java/com/couchbase/client/java/BinaryBinaryDocumentTest.java
new file mode 100644
index 0000000000000000000000000000000000000000..9dd356a399d822f50f7286b7dc61a35a00d0c9a4
--- /dev/null
+++ b/src/integration/java/com/couchbase/client/java/BinaryBinaryDocumentTest.java
@@ -0,0 +1,153 @@
+package com.couchbase.client.java;
+
+import com.couchbase.client.core.message.ResponseStatus;
+import com.couchbase.client.java.document.BinaryDocument;
+import com.couchbase.client.java.util.TestProperties;
+import org.junit.AfterClass;
+import org.junit.BeforeClass;
+import org.junit.Test;
+import rx.Observable;
+import rx.functions.Action1;
+import rx.functions.Func1;
+import rx.observables.BlockingObservable;
+
+import java.util.Iterator;
+
+import static org.junit.Assert.assertEquals;
+import static org.junit.Assert.assertNull;
+
+public class BinaryBinaryDocumentTest {
+
+  private static final String seedNode = TestProperties.seedNode();
+  private static final String bucketName = TestProperties.bucket();
+  private static final String password = TestProperties.password();
+
+  private static Bucket bucket;
+
+  @BeforeClass
+  public static void connect() {
+    final CouchbaseCluster cluster = new CouchbaseCluster(seedNode);
+    bucket = cluster
+        .openBucket(bucketName, password)
+        .toBlocking()
+        .single();
+
+    cleanup();
+  }
+
+  @AfterClass
+  public static void tearDown() {
+    cleanup();
+  }
+
+  private static void cleanup()
+  {
+    Observable
+        .from("insert-binary", "upsert-binary", "upsert-binary-replace")
+        .doOnNext(new Action1<String>() {
+          @Override
+          public void call(final String id) {
+            bucket.remove(id, BinaryDocument.class);
+          }
+        })
+        .toBlocking()
+        .last();
+  }
+
+  @Test
+  public void shouldInsertAndGet() {
+    final String content = "{\"hello\":\"world\"}";
+    final BinaryDocument doc = BinaryDocument.create("insert-binary", content);
+    final BinaryDocument response = bucket
+        .insert(doc)
+        .flatMap(new Func1<BinaryDocument, Observable<BinaryDocument>>() {
+          @Override
+          public Observable<BinaryDocument> call(final BinaryDocument document) {
+            return bucket.get("insert-binary", BinaryDocument.class);
+          }
+        })
+        .toBlocking()
+        .single();
+
+    assertEquals(content, response.content());
+    assertEquals(ResponseStatus.SUCCESS, response.status());
+  }
+
+  @Test
+  public void shouldUpsertAndGet() {
+    final int content = Integer.MAX_VALUE;
+    final BinaryDocument doc = BinaryDocument.create("upsert-binary", content);
+    final BinaryDocument response = bucket
+        .upsert(doc)
+        .flatMap(new Func1<BinaryDocument, Observable<BinaryDocument>>() {
+          @Override
+          public Observable<BinaryDocument> call(final BinaryDocument document) {
+            return bucket.get("upsert-binary", BinaryDocument.class);
+          }
+        })
+        .toBlocking()
+        .single();
+
+    assertEquals(content, response.content());
+    assertEquals(ResponseStatus.SUCCESS, response.status());
+  }
+
+  @Test
+  public void shouldUpsertAndReplace() {
+    final Long content = 125312341L;
+    final String replacedContent = "I am the future!";
+
+    final BinaryDocument doc = BinaryDocument.create("upsert-binary-replace", content);
+    final BinaryDocument response = bucket
+        .upsert(doc)
+        .flatMap(new Func1<BinaryDocument, Observable<BinaryDocument>>() {
+          @Override
+          public Observable<BinaryDocument> call(final BinaryDocument document) {
+
+            assertEquals(content, document.content());
+
+            return bucket.get("upsert-binary-replace", BinaryDocument.class);
+          }
+        })
+        .toBlocking()
+        .single();
+
+    assertEquals(content, response.content());
+
+    final BinaryDocument updated = BinaryDocument.from(response, replacedContent);
+    final BinaryDocument replaced = bucket
+        .replace(updated)
+        .flatMap(new Func1<BinaryDocument, Observable<BinaryDocument>>() {
+          @Override
+          public Observable<BinaryDocument> call(final BinaryDocument document) {
+            return bucket.get("upsert-binary-replace", BinaryDocument.class);
+          }
+        })
+        .toBlocking()
+        .single();
+
+    assertEquals(replacedContent, replaced.content());
+  }
+
+  @Test
+  public void shouldLoadMultipleDocuments() throws Exception {
+    final BlockingObservable<BinaryDocument> observable = Observable
+        .from("doc1", "doc2", "doc3")
+        .flatMap(new Func1<String, Observable<BinaryDocument>>() {
+          @Override
+          public Observable<BinaryDocument> call(final String id) {
+            return bucket.get(id, BinaryDocument.class);
+          }
+        })
+        .toBlocking();
+
+    final Iterator<BinaryDocument> iterator = observable.getIterator();
+    while (iterator.hasNext()) {
+      final BinaryDocument doc = iterator.next();
+
+      assertNull(doc.content());
+      assertEquals(ResponseStatus.NOT_EXISTS, doc.status());
+    }
+  }
+
+}
diff --git a/src/integration/java/com/couchbase/client/java/BinaryJsonDocumentTest.java b/src/integration/java/com/couchbase/client/java/BinaryJsonDocumentTest.java
new file mode 100644
index 0000000000000000000000000000000000000000..ba83a8052db9e316a6532071f254a2836039f705
--- /dev/null
+++ b/src/integration/java/com/couchbase/client/java/BinaryJsonDocumentTest.java
@@ -0,0 +1,149 @@
+package com.couchbase.client.java;
+
+import com.couchbase.client.core.message.ResponseStatus;
+import com.couchbase.client.java.document.JsonDocument;
+import com.couchbase.client.java.document.json.JsonObject;
+import com.couchbase.client.java.util.TestProperties;
+import org.junit.AfterClass;
+import org.junit.BeforeClass;
+import org.junit.Test;
+import rx.Observable;
+import rx.functions.Action1;
+import rx.functions.Func1;
+import rx.observables.BlockingObservable;
+
+import java.util.Iterator;
+
+import static org.junit.Assert.assertEquals;
+import static org.junit.Assert.assertNull;
+
+public class BinaryJsonDocumentTest {
+
+  private static final String seedNode = TestProperties.seedNode();
+  private static final String bucketName = TestProperties.bucket();
+  private static final String password = TestProperties.password();
+
+  private static Bucket bucket;
+
+  @BeforeClass
+  public static void connect() {
+    CouchbaseCluster cluster = new CouchbaseCluster(seedNode);
+    bucket = cluster
+        .openBucket(bucketName, password)
+        .toBlocking()
+        .single();
+
+    cleanup();
+  }
+
+  @AfterClass
+  public static void tearDown() {
+    cleanup();
+  }
+
+  private static void cleanup()
+  {
+    Observable
+        .from("insert", "upsert", "upsert-r")
+        .doOnNext(new Action1<String>() {
+          @Override
+          public void call(final String id) {
+            bucket.remove(id, JsonDocument.class);
+          }
+        })
+        .toBlocking()
+        .last();
+  }
+
+  @Test
+  public void shouldInsertAndGet() {
+    final JsonObject content = JsonObject.empty().put("hello", "world");
+    final JsonDocument doc = JsonDocument.create("insert", content);
+    final JsonDocument response = bucket
+        .insert(doc)
+        .flatMap(new Func1<JsonDocument, Observable<JsonDocument>>() {
+          @Override
+          public Observable<JsonDocument> call(final JsonDocument document) {
+            return bucket.get("insert");
+          }
+        })
+        .toBlocking()
+        .single();
+
+    assertEquals(content.getString("hello"), response.content().getString("hello"));
+  }
+
+  @Test
+  public void shouldUpsertAndGet() {
+    final JsonObject content = JsonObject.empty().put("hello", "world");
+    final JsonDocument doc = JsonDocument.create("upsert", content);
+    final JsonDocument response = bucket
+        .upsert(doc)
+        .flatMap(new Func1<JsonDocument, Observable<JsonDocument>>() {
+          @Override
+          public Observable<JsonDocument> call(final JsonDocument document) {
+            return bucket.get("upsert");
+          }
+        })
+        .toBlocking()
+        .single();
+
+    assertEquals(content.getString("hello"), response.content().getString("hello"));
+    assertEquals(ResponseStatus.SUCCESS, response.status());
+  }
+
+  @Test
+  public void shouldUpsertAndReplace() {
+    final JsonObject content = JsonObject.empty().put("hello", "world");
+    final JsonDocument doc = JsonDocument.create("upsert-r", content);
+
+    final JsonDocument response = bucket
+        .upsert(doc)
+        .flatMap(new Func1<JsonDocument, Observable<JsonDocument>>() {
+          @Override
+          public Observable<JsonDocument> call(final JsonDocument document) {
+            return bucket.get("upsert-r");
+          }
+        })
+        .toBlocking()
+        .single();
+
+    assertEquals(content.getString("hello"), response.content().getString("hello"));
+
+    final JsonDocument updated = JsonDocument.from(response, JsonObject.empty().put("hello", "replaced"));
+    final JsonDocument replacedResponse = bucket
+        .replace(updated)
+        .flatMap(new Func1<JsonDocument, Observable<JsonDocument>>() {
+          @Override
+          public Observable<JsonDocument> call(final JsonDocument document) {
+            return bucket.get("upsert-r");
+          }
+        })
+        .toBlocking()
+        .single();
+
+    assertEquals("replaced", replacedResponse.content().getString("hello"));
+  }
+
+  @Test
+  public void shouldLoadMultipleDocuments() throws Exception {
+    final BlockingObservable<JsonDocument> observable = Observable
+        .from("doc1", "doc2", "doc3")
+        .flatMap(new Func1<String, Observable<JsonDocument>>() {
+          @Override
+          public Observable<JsonDocument> call(final String id) {
+            return bucket.get(id);
+          }
+        })
+        .toBlocking();
+
+    final Iterator<JsonDocument> iterator = observable.getIterator();
+    while (iterator.hasNext()) {
+      final JsonDocument doc = iterator.next();
+
+      assertNull(doc.content());
+      assertEquals(ResponseStatus.NOT_EXISTS, doc.status());
+    }
+  }
+
+}
