diff --git a/src/main/java/com/couchbase/client/java/convert/BinaryConverter.java b/src/main/java/com/couchbase/client/java/convert/BinaryConverter.java
new file mode 100644
index 0000000000000000000000000000000000000000..fa395cd05c16858c569f0aa14e01067188c38298
--- /dev/null
+++ b/src/main/java/com/couchbase/client/java/convert/BinaryConverter.java
@@ -0,0 +1,157 @@
+/**
