     @SuppressWarnings("unchecked")
     public <D extends Document<?>> Observable<D> insert(final D document) {
diff --git a/src/main/java/com/couchbase/client/java/ReplicaMode.java b/src/main/java/com/couchbase/client/java/ReplicaMode.java
new file mode 100644
index 0000000000000000000000000000000000000000..79df50f15c383c4c970a04ed9eaa576b6a0be833
--- /dev/null
+++ b/src/main/java/com/couchbase/client/java/ReplicaMode.java
@@ -0,0 +1,30 @@
+package com.couchbase.client.java;
+
+/**
+ * The mode of the replica read to perform.
+ *
+ * @author Michael Nitschinger
+ * @since 2.0
+ */
+public enum ReplicaMode {
+
+    /**
+     * Asks all replicas and the active node and returns documents from those that respond.
+     */
+    ALL,
+
+    /**
+     * Only asks the first replica for its document.
+     */
+    FIRST,
+
+    /**
+     * Only asks the second replica for its document.
+     */
+    SECOND,
+
+    /**
+     * Only asks the third replica for its document.
+     */
+    THIRD
+}

