diff --git a/src/main/java/com/couchbase/client/java/bucket/DefaultBucketInfo.java b/src/main/java/com/couchbase/client/java/bucket/DefaultBucketInfo.java
new file mode 100644
index 0000000000000000000000000000000000000000..2b2ec72915b7506aa312a13eff39094f85da7f5f
--- /dev/null
+++ b/src/main/java/com/couchbase/client/java/bucket/DefaultBucketInfo.java
@@ -0,0 +1,46 @@
+package com.couchbase.client.java.bucket;
+
+import com.couchbase.client.java.document.json.JsonObject;
+
+public class DefaultBucketInfo implements BucketInfo {
+
+    private final JsonObject raw;
+
+    DefaultBucketInfo(JsonObject raw) {
+        this.raw = raw;
+    }
+
+    public DefaultBucketInfo create(JsonObject raw) {
+        return new DefaultBucketInfo(raw);
+    }
+
+    @Override
+    public String name() {
+        return raw.getString("name");
+    }
+
+    @Override
+    public BucketType type() {
+        String type = raw.getString("bucketType");
+        if (type.equals("membase")) {
+            return BucketType.COUCHBASE;
+        } else {
+            return BucketType.MEMCACHED;
+        }
+    }
+
+    @Override
+    public int nodeCount() {
+        return raw.getArray("nodes").size();
+    }
+
+    @Override
+    public int replicaCount() {
+        return raw.getInt("replicaNumber");
+    }
+
+    @Override
+    public JsonObject raw() {
+        return raw;
+    }
+}

