 package com.couchbase.client.java.bucket;

 import com.couchbase.client.java.document.json.JsonObject;

+/**
+ * Represents information about a bucket.
+ *
+ * Some bucket properties are accessible over getter methods, the full raw JSON response is accessible through the
+ * {@link #raw()} method.
+ *
+ * @author Michael Nitschinger
+ * @since 2.0
+ */
 public interface BucketInfo {

+    /**
+     * The name of the bucket.
+     *
+     * @return the bucket name.
+     */
     String name();

+    /**
+     * The type of the bucket.
+     *
+     * @return the bucket type.
+     */
     BucketType type();

+    /**
+     * The number of nodes on the bucket.
+     *
+     * @return number of nodes.
+     */
     int nodeCount();

+    /**
+     * The number of replicas configured.
+     *
+     * @return number of replicas configured.
+     */
     int replicaCount();

+    /**
+     * Raw JSON server response for advanced analysis.
+     *
+     * @return the raw JSON bucket info.
+     */
     JsonObject raw();

 }
