+        return publishDesignDocument(name, overwrite, timeout, TIMEOUT_UNIT);
+    }
+
+    @Override
+    public BucketInfo info(final long timeout, final TimeUnit timeUnit) {
+        return asyncBucketManager
+            .info()
+            .timeout(timeout, timeUnit)
