diff --git a/src/integration/java/com/couchbase/client/java/ViewQueryTest.java b/src/integration/java/com/couchbase/client/java/ViewQueryTest.java
new file mode 100644
index 0000000000000000000000000000000000000000..246a1aa4822486051f3662a941cb805a583fdad7
--- /dev/null
+++ b/src/integration/java/com/couchbase/client/java/ViewQueryTest.java
@@ -0,0 +1,235 @@
+/**
+ * Copyright (C) 2014 Couchbase, Inc.
+ *
+ * Permission is hereby granted, free of charge, to any person obtaining a copy
+ * of this software and associated documentation files (the "Software"), to deal
+ * in the Software without restriction, including without limitation the rights
