diff --git a/src/main/java/com/couchbase/client/java/view/ViewQueryResponseMapper.java b/src/main/java/com/couchbase/client/java/view/ViewQueryResponseMapper.java
new file mode 100644
index 0000000000000000000000000000000000000000..33e58c4b2c1898f4bc882db9a486e529be2a0bfd
--- /dev/null
+++ b/src/main/java/com/couchbase/client/java/view/ViewQueryResponseMapper.java
@@ -0,0 +1,141 @@
+/**
+ * Copyright (C) 2014 Couchbase, Inc.
+ *
+ * Permission is hereby granted, free of charge, to any person obtaining a copy
+ * of this software and associated documentation files (the "Software"), to deal
+ * in the Software without restriction, including without limitation the rights
