new file mode 100644
index 0000000000000000000000000000000000000000..9426973ae8086a0383d90db9391867f17697b88f
--- /dev/null
+++ b/src/main/java/com/couchbase/client/java/logging/log4j/AbstractAppender.java
@@ -0,0 +1,216 @@
+package com.couchbase.client.java.logging.log4j;
+
+import com.couchbase.client.core.logging.CouchbaseLoggerFactory;
+import com.couchbase.client.core.logging.Log4JLoggerFactory;
+import com.couchbase.client.java.Bucket;
+import com.couchbase.client.java.Cluster;
+import com.couchbase.client.java.CouchbaseCluster;
+import com.couchbase.client.java.document.JsonDocument;
+import com.couchbase.client.java.document.json.JsonArray;
+import com.couchbase.client.java.document.json.JsonObject;
+import org.apache.log4j.AppenderSkeleton;
+import org.apache.log4j.Level;
+import org.apache.log4j.LogManager;
+import org.apache.log4j.MDC;
+import org.apache.log4j.helpers.LogLog;
+import org.apache.log4j.spi.LoggingEvent;
+
+import java.util.Arrays;
+import java.util.Calendar;
+import java.util.Map;
+import java.util.UUID;
+
+
+public abstract class AbstractAppender extends AppenderSkeleton {
+
+
+    public static final String LEVEL = "level";
+    public static final String NAME = "name";
+    public static final String APP_ID = "applicationId";
+    public static final String TIMESTAMP = "timestamp";
+    public static final String PROPERTIES = "properties";
+    public static final String TRACEBACK = "traceback";
+    public static final String MESSAGE = "message";
+    public static final String YEAR = "year";
+    public static final String MONTH = "month";
+    public static final String DAY = "day";
+    public static final String HOUR = "hour";
+
+    private String bucket = "logs";
+    private String password = "";
+    private String hosts = "127.0.0.1";
+    private int expiry = 0;
+
+    private volatile Bucket bucketRef = null;
+    private volatile boolean failedBootstrap = false;
+
+    protected String applicationId = System.getProperty("APPLICATION_ID", null);
+
+    static {
+        CouchbaseLoggerFactory.setDefaultFactory(new Log4JLoggerFactory());
+    }
+
+    protected AbstractAppender() {
+    }
+
+    protected AbstractAppender(boolean isActive) {
+        super(isActive);
+    }
+
+    public String getHosts() {
+        return hosts;
+    }
+
+    public void setHosts(String hosts) {
+        this.hosts = hosts;
+    }
+
+    public String getBucket() {
+        return bucket;
+    }
+
+    public void setBucket(String bucket) {
+        this.bucket = bucket;
+    }
+
+    public String getPassword() {
+        return password;
+    }
+
+    public void setPassword(String password) {
+        this.password = password;
+    }
+
+    public String getApplicationId() {
+        return applicationId;
+    }
+
+    public void setApplicationId(String applicationId) {
+        this.applicationId = applicationId;
+    }
+
+    public Bucket getBucketRef() {
+        return bucketRef;
+    }
+
+    public void setBucketRef(Bucket bucketRef) {
+        this.bucketRef = bucketRef;
+    }
+
+    public int getExpiry() {
+        return expiry;
+    }
+
+    public void setExpiry(int expiry) {
+        this.expiry = expiry;
+    }
+
+    private synchronized void connect() {
+        if (bucketRef != null ||  failedBootstrap) {
+            return;
+        }
+
+        Level global = LogManager.getLoggerRepository().getThreshold();
+
+        try {
+            LogManager.getLoggerRepository().setThreshold(Level.OFF);
+            Cluster cluster = hosts.contains(",")
+                ? CouchbaseCluster.create(hosts.split(",")) : CouchbaseCluster.create(hosts);
+            bucketRef = cluster.openBucket(bucket, password);
+        } catch(Throwable err) {
+            failedBootstrap = true;
+            LogLog.error("Could not initialize Couchbase Logger", err);
+            errorHandler.error("Could not initialize Couchbase Logger" + err);
+        } finally {
+            LogManager.getLoggerRepository().setThreshold(global);
+        }
+    }
+
+    protected abstract void doAppend(JsonDocument document);
+
+    @Override
+    @SuppressWarnings({ "unchecked" })
+    protected void append(final LoggingEvent event) {
+        if (failedBootstrap) {
+            return;
+        }
+
+        if (bucketRef == null) {
+            connect();
+            if (failedBootstrap || bucketRef == null) {
+                return;
+            }
+        }
+
+        JsonObject target = JsonObject.create();
+
+        if (null != applicationId) {
+            target.put(APP_ID, applicationId);
+            MDC.put(APP_ID, applicationId);
+        }
+
+        // Set logger name, level and timestamp
+        target.put(NAME, event.getLogger().getName());
+        target.put(LEVEL, event.getLevel().toString());
+        target.put(TIMESTAMP, event.getTimeStamp());
+
+        // Set properties
+        Map<Object, Object> props = event.getProperties();
+        if (props.size() > 0) {
+            JsonObject propsObj = JsonObject.create();
+            for (Map.Entry<Object, Object> entry : props.entrySet()) {
+                propsObj.put(entry.getKey().toString(), entry.getValue().toString());
+            }
+            target.put(PROPERTIES, propsObj);
+        }
+
+        // Set traceback info if any
+        String[] traceback = event.getThrowableStrRep();
+        if (null != traceback && traceback.length > 0) {
+            target.put(TRACEBACK, JsonArray.from(Arrays.asList(traceback)));
+        }
+
+        // Set the message
+        target.put(MESSAGE, event.getRenderedMessage());
+
+        // Update the log context
+        Calendar now = Calendar.getInstance();
+        MDC.put(YEAR, now.get(Calendar.YEAR));
+        MDC.put(MONTH, String.format("%1$02d", now.get(Calendar.MONTH) + 1));
+        MDC.put(DAY, String.format("%1$02d", now.get(Calendar.DAY_OF_MONTH)));
+        MDC.put(HOUR, String.format("%1$02d", now.get(Calendar.HOUR_OF_DAY)));
+
+        MDC.remove(YEAR);
+        MDC.remove(MONTH);
+        MDC.remove(DAY);
+        MDC.remove(HOUR);
+        if (null != applicationId) {
+            MDC.remove(APP_ID);
+        }
+
+        doAppend(JsonDocument.create(generateId(), expiry, target));
+
+    }
+
+    @Override
+    public void close() {
+        if (bucketRef != null) {
+            bucketRef.close();
+        }
+    }
+
+    @Override
+    public boolean requiresLayout() {
+        return false;
+    }
+
+    /**
+     * Generates a unique ID used for the document id.
+     *
+     * @return the unique document ID.
+     */
+    private static String generateId() {
+        return UUID.randomUUID().toString();
+    }
+
+}
diff --git a/src/main/java/com/couchbase/client/java/logging/log4j/CouchbaseAppender.java b/src/main/java/com/couchbase/client/java/logging/log4j/CouchbaseAppender.java
new file mode 100644
index 0000000000000000000000000000000000000000..9552ac85d8a52e1f8ffbaeb95cb97bc3a46369c0
--- /dev/null
+++ b/src/main/java/com/couchbase/client/java/logging/log4j/CouchbaseAppender.java
@@ -0,0 +1,34 @@
+package com.couchbase.client.java.logging.log4j;
+
+import com.couchbase.client.core.annotations.InterfaceAudience;
+import com.couchbase.client.core.annotations.InterfaceStability;
+import com.couchbase.client.java.document.JsonDocument;
+import org.apache.log4j.helpers.LogLog;
+
+/**
+ * A Couchbase-backed synchronous Log4j Appender.
+ *
+ * @author Michael Nitschinger
+ * @since 2.0.2
+ */
+@InterfaceStability.Experimental
+@InterfaceAudience.Public
+public class CouchbaseAppender extends AbstractAppender {
+
+    public CouchbaseAppender() {
+    }
+
+    public CouchbaseAppender(boolean isActive) {
+        super(isActive);
+    }
+
+    @Override
+    protected void doAppend(final JsonDocument document) {
+        try {
+            getBucketRef().insert(document);
+        } catch(Exception ex) {
+            LogLog.error("Could not Log message", ex);
+            errorHandler.error("Could not Log Message" + ex);
+        }
+    }
+}
diff --git a/src/main/java/com/couchbase/client/java/logging/log4j/CouchbaseAsyncAppender.java b/src/main/java/com/couchbase/client/java/logging/log4j/CouchbaseAsyncAppender.java
new file mode 100644
index 0000000000000000000000000000000000000000..afb09e4a92fe2d366380cfc6f04f2eeff4006857
--- /dev/null
+++ b/src/main/java/com/couchbase/client/java/logging/log4j/CouchbaseAsyncAppender.java
@@ -0,0 +1,40 @@
+package com.couchbase.client.java.logging.log4j;
+
+import com.couchbase.client.core.annotations.InterfaceAudience;
+import com.couchbase.client.core.annotations.InterfaceStability;
+import com.couchbase.client.java.document.JsonDocument;
+import org.apache.log4j.helpers.LogLog;
+import rx.functions.Action1;
+
+/**
+ * A Couchbase-backed synchronous Log4j Appender.
+ *
+ * @author Michael Nitschinger
+ * @since 2.0.2
+ */
+@InterfaceStability.Experimental
+@InterfaceAudience.Public
+public class CouchbaseAsyncAppender extends AbstractAppender {
+
+    public CouchbaseAsyncAppender() {
+    }
+
+    public CouchbaseAsyncAppender(boolean isActive) {
+        super(isActive);
+    }
+
+    @Override
+    protected void doAppend(final JsonDocument document) {
+        getBucketRef()
+            .async()
+            .insert(document)
+            .doOnError(new Action1<Throwable>() {
+                @Override
+                public void call(Throwable ex) {
+                    LogLog.error("Could not Log message", ex);
+                    errorHandler.error("Could not Log Message" + ex);
+                }
+            })
+            .subscribe();
+    }
+}
diff --git a/src/main/java/com/couchbase/client/java/logging/log4j/README.md b/src/main/java/com/couchbase/client/java/logging/log4j/README.md
new file mode 100644
index 0000000000000000000000000000000000000000..b6f395a0a75faad8dc38749bdf7409aa030f99ee
--- /dev/null
+++ b/src/main/java/com/couchbase/client/java/logging/log4j/README.md
@@ -0,0 +1,102 @@
+# Couchbase Log4j Appenders
+This package provides Log appenders for the Log4j project. The main goal is to log events to a Couchbase Server
+bucket, instead (or in addition to) regular log files or other sources.
+
+## Configuration
+In addition to the Couchbase Java SDK, Log4j needs to be added as a dependency to your project.
+
+```xml
+<dependencies>
+    <dependency>
+        <groupId>com.couchbase.client</groupId>
+        <artifactId>java-client</artifactId>
+        <version>2.0.2</version>
+    </dependency>
+    <dependency>
+        <groupId>log4j</groupId>
+        <artifactId>log4j</artifactId>
+        <version>1.2.17</version>
+    </dependency>
+</dependencies>
+```
+
+Now the appender can be configured like any other, here is a `log4j.properties` with all possible options:
+
+```
+log4j.rootLogger=INFO, cb
+
+log4j.appender.cb=com.couchbase.client.java.logging.log4j.CouchbaseAppender
+log4j.appender.cb.applicationId=myApp
+log4j.appender.cb.hosts=127.0.0.1
+log4j.appender.cb.bucket=logs
+log4j.appender.cb.password=
+```
+
+If you want to stick with the defaults as shown (connect to `127.0.0.1` and use the `logs` bucket with no password), then
+you can also use this one-liner:
+
+```
+log4j.appender.cb=com.couchbase.client.java.logging.log4j.CouchbaseAppender
+```
+
+In addition to the synchronous appender, the same options are available for the `CouchbaseAsyncAppender`, which does
+not wait until the log insert completes, but just keeps moving on (errors are still logged through a callback to make
+it diagnosable).
+
+```
+log4j.appender.cb=com.couchbase.client.java.logging.log4j.CouchbaseAsyncAppender
+```
+
+Note that the async appender has the drawback that log entries might be lost in error situations, as well as you can't
+be sure that everything is logged during a shutdown, since no one waits until they are completely written. So only use
+it when you don't care about lost messages and want highest throughput without holding up the application.
+
+You can then start logging:
+
+```java
+import org.apache.log4j.Logger;
+
+public class Main {
+
+    private static Logger logger = Logger.getLogger(Main.class);
+
+    public static void main(String[] args) throws Exception {
+        logger.info("Hello World!");
+    }
+
+}
+```
+
+This will store a document looking like this in the bucket:
+
+```json
+{
+  "level": "INFO",
+  "name": "Main",
+  "applicationId": "testApp",
+  "message": "Hello World!",
+  "properties": {
+    "applicationId": "myApp"
+  },
+  "timestamp": 1416917036253
+}
+```
+
+If exceptions are logged, you get more context:
+
+```json
+  "level": "INFO",
+  "name": "Main",
+  "applicationId": "testApp",
+  "message": "Hello World!",
+  "traceback": [
+    "java.lang.Exception: This is an exception",
+    "\tat Main.main(Main.java:8)"
+  ],
+  "properties": {
+    "applicationId": "testApp"
+  },
+  "timestamp": 1416917227684
+}
+```
+

