diff --git a/src/main/java/com/couchbase/client/java/util/Blocking.java b/src/main/java/com/couchbase/client/java/util/Blocking.java
new file mode 100644
index 0000000000000000000000000000000000000000..952d98a8eacfb84449a3e11c88abfa03d1d040ba
--- /dev/null
+++ b/src/main/java/com/couchbase/client/java/util/Blocking.java
@@ -0,0 +1,111 @@
