+        assertTrue(mSub1 instanceof Map);
+        assertEquals("test", ((Map) mSub1).get("sub1.1"));
+
+        assertNotNull(mSub2);
+        assertTrue(mSub2 instanceof List);
+        assertEquals("sub2.1", ((List) mSub2).get(0));
+    }
+
+    @Test
