+        JsonArray arr = JsonArray.create();
+        try {
+            arr.add(arr);
+            fail();
+        } catch (IllegalArgumentException e) {
+            //success
+        }
+        try {
+            arr.add((Object) arr);
+            fail();
+        } catch (IllegalArgumentException e) {
+            //success
+        }
+    }
