+package com.couchbase.client.java.query;
+
+import static org.junit.Assert.assertEquals;
+import static org.junit.Assert.assertFalse;
+import static org.junit.Assert.assertNotNull;
+import static org.junit.Assert.assertTrue;
+
+import java.util.Arrays;
+import java.util.Collections;
+import java.util.Map;
+import java.util.concurrent.TimeUnit;
+
+import com.couchbase.client.java.document.json.JsonArray;
+import com.couchbase.client.java.document.json.JsonObject;
+import com.couchbase.client.java.query.consistency.ScanConsistency;
+import org.junit.Test;
+
+/**
+ * Tests on {@link QueryParams}.
+ *
+ * @author Simon Baslé
+ * @since 2.1
+ */
+public class QueryParamsTest {
+
+    @Test
+    public void shouldInjectCorrectConsistencies() {
+        QueryParams p = QueryParams.build().consistency(ScanConsistency.NOT_BOUNDED);
+
+        JsonObject actual = JsonObject.empty();
+        p.injectParams(actual);
+
+        assertEquals("not_bounded", actual.get("scan_consistency"));
+
+        p.consistency(ScanConsistency.REQUEST_PLUS);
+        p.injectParams(actual);
+        assertEquals(1, actual.size());
+        assertEquals("request_plus", actual.getString("scan_consistency"));
+
+        p.consistency(ScanConsistency.STATEMENT_PLUS);
+        p.injectParams(actual);
+        assertEquals(1, actual.size());
+        assertEquals("statement_plus", actual.getString("scan_consistency"));
+    }
+
+    @Test
+    public void consistencyNotBoundedShouldEraseScanWaitAndVector() {
+        QueryParams p = QueryParams.build()
+            .scanWait(12, TimeUnit.SECONDS)
+            .consistency(ScanConsistency.NOT_BOUNDED);
+
+        JsonObject expected = JsonObject.create()
+            .put("scan_consistency", "not_bounded");
+        JsonObject actual = JsonObject.empty();
+        p.injectParams(actual);
+
+        assertEquals(expected, actual);
+    }
+
+    @Test
+    public void shouldIgnoreScanWaitIfConsistencyNotBounded() {
+        QueryParams p = QueryParams.build()
+           .consistency(ScanConsistency.NOT_BOUNDED)
+           .scanWait(12, TimeUnit.SECONDS);
+
+        JsonObject expected = JsonObject.create()
+            .put("scan_consistency", "not_bounded");
+        JsonObject actual = JsonObject.empty();
+        p.injectParams(actual);
+
+        assertEquals(expected, actual);
+    }
+
+    @Test
+    public void shouldAllowScanWaitOnlyForCorrectConsistencies() {
+        QueryParams p = QueryParams.build()
+                                   .scanWait(12, TimeUnit.SECONDS)
+                                   .consistency(ScanConsistency.REQUEST_PLUS);
+
+        JsonObject actual = JsonObject.empty();
+        p.injectParams(actual);
+        assertEquals("12s", actual.getString("scan_wait"));
+
+        actual = JsonObject.empty();
+        p.injectParams(actual);
+        assertEquals("12s", actual.getString("scan_wait"));
+
+        p.consistency(ScanConsistency.STATEMENT_PLUS);
+
+        actual = JsonObject.empty();
+        p.injectParams(actual);
+        assertEquals("12s", actual.getString("scan_wait"));
+
+        p.consistency(ScanConsistency.NOT_BOUNDED);
+        actual = JsonObject.empty();
+        assertFalse(actual.containsKey("scan_wait"));
+
+    }
+
+    @Test
+    public void shouldInjectClientId() {
+        QueryParams p = QueryParams.build()
+                                   .withContextId("test");
+
+        JsonObject expected = JsonObject.create()
+                                        .put("client_context_id", "test");
+        JsonObject actual = JsonObject.empty();
+        p.injectParams(actual);
+
+        assertEquals(expected, actual);
+    }
+
+    @Test
+    public void shouldInjectTimeoutNanos() {
+        QueryParams p = QueryParams.build().serverSideTimeout(24, TimeUnit.NANOSECONDS);
+
+        JsonObject expected = JsonObject.create().put("timeout", "24ns");
+        JsonObject actual = JsonObject.empty();
+        p.injectParams(actual);
+
+        assertEquals(expected, actual);
+    }
+    @Test
+    public void shouldInjectTimeoutMicros() {
+        QueryParams p = QueryParams.build().serverSideTimeout(24, TimeUnit.MICROSECONDS);
+
+        JsonObject expected = JsonObject.create().put("timeout", "24us");
+        JsonObject actual = JsonObject.empty();
+        p.injectParams(actual);
+
+        assertEquals(expected, actual);
+    }
+    @Test
+    public void shouldInjectTimeoutMillis() {
+        QueryParams p = QueryParams.build().serverSideTimeout(24, TimeUnit.MILLISECONDS);
+
+        JsonObject expected = JsonObject.create().put("timeout", "24ms");
+        JsonObject actual = JsonObject.empty();
+        p.injectParams(actual);
+
+        assertEquals(expected, actual);
+    }
+    @Test
+    public void shouldInjectTimeoutSeconds() {
+        QueryParams p = QueryParams.build().serverSideTimeout(24, TimeUnit.SECONDS);
+
+        JsonObject expected = JsonObject.create().put("timeout", "24s");
+        JsonObject actual = JsonObject.empty();
+        p.injectParams(actual);
+
+        assertEquals(expected, actual);
+    }
+    @Test
+    public void shouldInjectTimeoutMinutes() {
+        QueryParams p = QueryParams.build().serverSideTimeout(24, TimeUnit.MINUTES);
+
+        JsonObject expected = JsonObject.create().put("timeout", "24m");
+        JsonObject actual = JsonObject.empty();
+        p.injectParams(actual);
+
+        assertEquals(expected, actual);
+    }
+
+    @Test
+    public void shouldInjectTimeoutHours() {
+        QueryParams p = QueryParams.build().serverSideTimeout(24, TimeUnit.HOURS);
+
+        JsonObject expected = JsonObject.create().put("timeout", "24h");
+        JsonObject actual = JsonObject.empty();
+        p.injectParams(actual);
+
+        assertEquals(expected, actual);
+    }
+
+    @Test
+    public void shouldInjectTimeoutHoursIfDays() {
+        QueryParams p = QueryParams.build().serverSideTimeout(2, TimeUnit.DAYS);
+
+        JsonObject expected = JsonObject.create().put("timeout", "48h");
+        JsonObject actual = JsonObject.empty();
+        p.injectParams(actual);
+
+        assertEquals(expected, actual);
+    }
+
+    @Test
+    public void shouldDoNothingIfParamsEmpty() {
+        QueryParams p = QueryParams.build();
+        JsonObject empty = JsonObject.empty();
+        p.injectParams(empty);
+
+        assertTrue(empty.isEmpty());
+    }
+}
diff --git a/src/test/java/com/couchbase/client/java/query/QueryToN1qlTest.java b/src/test/java/com/couchbase/client/java/query/QueryToN1qlTest.java
new file mode 100644
index 0000000000000000000000000000000000000000..a72730ea28233f8b68ca3de282e205da22349ff6
--- /dev/null
+++ b/src/test/java/com/couchbase/client/java/query/QueryToN1qlTest.java
@@ -0,0 +1,170 @@
+/*
+ * Copyright (C) 2014 Couchbase, Inc.
+ *
+ * Permission is hereby granted, free of charge, to any person obtaining a copy
+ * of this software and associated documentation files (the "Software"), to deal
+ * in the Software without restriction, including without limitation the rights
+ * to use, copy, modify, merge, publish, distribute, sublicense, and/or sell
+ * copies of the Software, and to permit persons to whom the Software is
+ * furnished to do so, subject to the following conditions:
+ *
+ * The above copyright notice and this permission notice shall be included in
+ * all copies or substantial portions of the Software.
+ *
+ * THE SOFTWARE IS PROVIDED "AS IS", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR
+ * IMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY,
+ * FITNESS FOR A PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE
+ * AUTHORS OR COPYRIGHT HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER
+ * LIABILITY, WHETHER IN AN ACTION OF CONTRACT, TORT OR OTHERWISE, ARISING
+ * FROM, OUT OF OR IN CONNECTION WITH THE SOFTWARE OR THE USE OR OTHER DEALING
+ * IN THE SOFTWARE.
+ */
+
+package com.couchbase.client.java.query;
+
+import static com.couchbase.client.java.query.Select.select;
+import static com.couchbase.client.java.query.dsl.Expression.s;
+import static com.couchbase.client.java.query.dsl.Expression.x;
+import static org.junit.Assert.assertEquals;
+
+import java.util.Collections;
+import java.util.concurrent.TimeUnit;
+
+import com.couchbase.client.java.document.json.JsonArray;
+import com.couchbase.client.java.document.json.JsonObject;
+import com.couchbase.client.java.query.consistency.ScanConsistency;
+import org.junit.Test;
+
+/**
+ * Verifies various combinations of N1QL queries and their transformation to N1QL string.
+ *
+ * @author Simon Baslé
+ * @since 2.1
+ */
+public class QueryToN1qlTest {
+
+    @Test
+    public void simpleQueryShouldJustProduceStatement() {
+        SimpleQuery query = new SimpleQuery(select("*").from("tutorial").where(x("fname").eq(s("ian"))), null);
+
+        //notice ian is between escaped quotes since inside json
+        assertEquals("{\"statement\":\"SELECT * FROM tutorial WHERE fname = \\\"ian\\\"\"}", query.n1ql().toString());
+    }
+
+    @Test
+    public void rawSimpleQueryShouldJustProduceStatementAsIs() {
+        SimpleQuery query = Query.simple("Here goes anything even not \"JSON\"");
+
+        //notice JSON is between escaped quotes since inside json
+        assertEquals("{\"statement\":\"Here goes anything even not \\\"JSON\\\"\"}", query.n1ql().toString());
+    }
+
+    @Test
+    public void parametrizedQueryWithArrayShouldProduceStatementAndArgs() {
+        ParametrizedQuery query = new ParametrizedQuery(select("*"), JsonArray.from("aString", 123, true), null);
+
+        JsonObject expected = JsonObject.create()
+            .put("statement", "SELECT *")
+            .put("args", JsonArray.from("aString", 123, true));
+
+        assertEquals(expected, query.n1ql());
+    }
+
+    @Test(expected = IllegalArgumentException.class)
+    public void shouldRefuseToPrepareQueryPlan() {
+        QueryPlan fakePlan = new QueryPlan(JsonObject.empty());
+        PrepareStatement.prepare(fakePlan);
+    }
+
+    @Test
+    public void shouldNotWrapAPrepareStatement() {
+        PrepareStatement statement = PrepareStatement.prepare(select("*"));
+        assertEquals(statement, PrepareStatement.prepare(statement));
+    }
+
+    @Test
+    public void shouldPrependStatementWithPrepare() {
+        Statement toPrepare = select("*").from("default");
+        PrepareStatement prepare = PrepareStatement.prepare(toPrepare);
+
+        assertEquals("PREPARE SELECT * FROM default", prepare.toString());
+    }
+
+    @Test
+    public void preparedQueryWithArrayShouldProducePreparedAndArgs() {
+        JsonObject rawPlan = JsonObject.create().put("fake", "select *");
+        QueryPlan fakePlan = new QueryPlan(rawPlan);
+        JsonArray params =JsonArray.from("aString", 123, true);
+        PreparedQuery query = new PreparedQuery(fakePlan, params, null);
+
+        JsonObject expected = JsonObject.create()
+            .put("prepared", rawPlan)
+            .put("args", JsonArray.from("aString", 123, true));
+
+        assertEquals(expected, query.n1ql());
+    }
+
+    @Test
+    public void parametrizedQueryWithObjectShouldProduceStatementAndNamedParameters() {
+        JsonObject args = JsonObject.create()
+            .put("myParamString", "aString")
+            .put("someInt", 123)
+            .put("$fullN1qlParam", true);
+        ParametrizedQuery query = new ParametrizedQuery(select("*"), args, null);
+
+        JsonObject expected = JsonObject.create()
+            .put("statement", "SELECT *")
+            .put("$myParamString", "aString")
+            .put("$someInt", 123)
+            .put("$fullN1qlParam", true);
+
+        assertEquals(expected, query.n1ql());
+    }
+
+    @Test
+    public void preparedQueryWithObjectShouldProducePreparedAndNamedParameters() {
+        JsonObject rawPlan = JsonObject.create().put("fake", "select *");
+        QueryPlan fakePlan = new QueryPlan(rawPlan);
+        JsonObject args = JsonObject.create()
+            .put("myParamString", "aString")
+            .put("someInt", 123)
+            .put("$fullN1qlParam", true);
+        PreparedQuery query = new PreparedQuery(fakePlan, args, null);
+
+        JsonObject expected = JsonObject.create()
+            .put("prepared", rawPlan)
+            .put("$myParamString", "aString")
+            .put("$someInt", 123)
+            .put("$fullN1qlParam", true);
+
+        assertEquals(expected, query.n1ql());
+    }
+
+    @Test
+    public void queryParamsShouldBeInjectedInQuery() {
+        QueryParams fullParams = QueryParams.build()
+                .consistency(ScanConsistency.REQUEST_PLUS)
+                .scanWait(12, TimeUnit.SECONDS)
+                .serverSideTimeout(20, TimeUnit.SECONDS)
+                .withContextId("test");
+
+        JsonObject expected = JsonObject.create()
+                .put("statement", "SELECT * FROM default")
+                .put("scan_consistency", "request_plus")
+                .put("scan_wait", "12s")
+                .put("timeout", "20s")
+                .put("client_context_id", "test");
+
+        SimpleQuery query1 = new SimpleQuery(select(x("*")).from("default"), fullParams);
+        assertEquals(expected, query1.n1ql());
+
+        ParametrizedQuery query2 = new ParametrizedQuery(select(x("*")).from("default"), JsonObject.empty(), fullParams);
+        assertEquals(expected, query2.n1ql());
+
+        JsonObject fakePlan = JsonObject.create().put("fake", "select *");
+        expected.removeKey("statement").put("prepared", fakePlan);
+        PreparedQuery query3 = new PreparedQuery(new QueryPlan(fakePlan), JsonArray.empty(), fullParams);
+        assertEquals(expected, query3.n1ql());
+    }
+
+}
diff --git a/src/test/java/com/couchbase/client/java/query/dsl/ExpressionTest.java b/src/test/java/com/couchbase/client/java/query/dsl/ExpressionTest.java
index 108f0075939217fc01566912ead8f891afb30a0c..0c53af34e5b035bb85f63d945484aa306051ff18 100644
--- a/src/test/java/com/couchbase/client/java/query/dsl/ExpressionTest.java
+++ b/src/test/java/com/couchbase/client/java/query/dsl/ExpressionTest.java
@@ -21,7 +21,32 @@
  */
 package com.couchbase.client.java.query.dsl;

+import static com.couchbase.client.java.query.dsl.Expression.i;
+import static org.junit.Assert.assertEquals;
+
+import com.couchbase.client.java.query.Select;
+import com.couchbase.client.java.query.Statement;
+import com.couchbase.client.java.query.dsl.path.AsPath;
+import org.junit.Test;
+
 public class ExpressionTest {

+    @Test
+    public void shouldEscapeOneIdentifier() {
+        Expression escaped = i("beer-sample");
+        assertEquals("`beer-sample`", escaped.toString());
+    }
+
+    @Test
+    public void shouldEscapedMultipleIdentifiers() {
+        Expression escaped = i("beer-sample", "someothersample", "third-sample");
+        assertEquals("`beer-sample`, `someothersample`, `third-sample`", escaped.toString());
+    }
+
+    @Test
+    public void shouldEscapeIdentifierInFromClause() {
+        Statement escapedFrom = Select.select("*").from(i("test"));
+        assertEquals("SELECT * FROM `test`", escapedFrom.toString());
+    }

 }
