index 0000000000000000000000000000000000000000..ef51bd880489f26fa4ec33dac1fe6a145d1f276b
--- /dev/null
+++ b/src/main/java/com/couchbase/client/java/query/AbstractQuery.java
@@ -0,0 +1,83 @@
