diff --git a/src/main/java/com/couchbase/client/java/error/TemporaryLockFailureException.java b/src/main/java/com/couchbase/client/java/error/TemporaryLockFailureException.java
new file mode 100644
index 0000000000000000000000000000000000000000..cfcb60f3e4f4667f0192d10bccae219445adc3c7
--- /dev/null
+++ b/src/main/java/com/couchbase/client/java/error/TemporaryLockFailureException.java
@@ -0,0 +1,55 @@
+/**
+ * Copyright (C) 2015 Couchbase, Inc.
+ *
+ * Permission is hereby granted, free of charge, to any person obtaining a copy
+ * of this software and associated documentation files (the "Software"), to deal
+ * in the Software without restriction, including without limitation the rights
