+
+        JsonDocument storedRaw = bucket().get(user.id());
+        assertEquals("Michael", storedRaw.content().getString("name"));
+    }
+
+}
diff --git a/src/integration/java/com/couchbase/client/java/repository/User.java b/src/integration/java/com/couchbase/client/java/repository/User.java
