diff --git a/src/main/java/com/couchbase/client/java/repository/mapping/DefaultEntityConverter.java b/src/main/java/com/couchbase/client/java/repository/mapping/DefaultEntityConverter.java
index a92e21881f6541544e873e88bcb61f44267b15b9..077df00ed6392ced679883b7bf403ba85d779821 100644
--- a/src/main/java/com/couchbase/client/java/repository/mapping/DefaultEntityConverter.java
