diff --git a/src/main/java/com/couchbase/client/java/query/dsl/functions/Collections.java b/src/main/java/com/couchbase/client/java/query/dsl/functions/Collections.java
new file mode 100644
index 0000000000000000000000000000000000000000..26efd25b41e58a8046fdc1f13a0f9162240f6aa2
--- /dev/null
+++ b/src/main/java/com/couchbase/client/java/query/dsl/functions/Collections.java
@@ -0,0 +1,255 @@
+/**
+ * Copyright (C) 2015 Couchbase, Inc.
+ *
+ * Permission is hereby granted, free of charge, to any person obtaining a copy
+ * of this software and associated documentation files (the "Software"), to deal
+ * in the Software without restriction, including without limitation the rights
