+    @Override
+    public Statement withNode(String nodeName) {
+        return with(false, nodeName);
+    }
+
+    @Override
+    public Statement withDefer() {
+        return with(true, null);
+    }
+
+    @Override
+    public Statement withDeferAndNode(String nodeName) {
+        return with(true, nodeName);
+    }
