new file mode 100644
index 0000000000000000000000000000000000000000..3e73d0b1c4206242ae2367cf3f45af8e048315b8
--- /dev/null
+++ b/src/test/java/com/couchbase/client/java/query/dsl/functions/CaseTest.java
@@ -0,0 +1,94 @@
+/*
