diff --git a/src/main/java/com/couchbase/client/java/query/NamedPreparedStatementException.java b/src/main/java/com/couchbase/client/java/query/NamedPreparedStatementException.java
new file mode 100644
index 0000000000000000000000000000000000000000..89132cb9934b72cd120726cf4680e8ae758fa236
--- /dev/null
+++ b/src/main/java/com/couchbase/client/java/query/NamedPreparedStatementException.java
@@ -0,0 +1,42 @@
+/**
