+package com.couchbase.client.java.query;
+
+import com.couchbase.client.core.CouchbaseException;
+
+/**
+ * An exception marking the fact that a Named Prepared Statement in N1QL couldn't be executed and
+ * that there was a fallback to re-preparing it.
+ *
+ * @author Simon Baslé
+ * @since 2.2
+ */
+public class NamedPreparedStatementException extends CouchbaseException {
+
+    public NamedPreparedStatementException(String message) {
+        super(message);
+    }
+
+    public NamedPreparedStatementException(String message, Throwable cause) {
+        super(message, cause);
+    }
+}
diff --git a/src/main/java/com/couchbase/client/java/query/PrepareStatement.java b/src/main/java/com/couchbase/client/java/query/PrepareStatement.java
index a24c32ab35bdb05a0bd58b037ebbbcc74fe00fcd..bd7ca7dcba7e5598bbd1836a8d430fca6f1444f1 100644
--- a/src/main/java/com/couchbase/client/java/query/PrepareStatement.java
+++ b/src/main/java/com/couchbase/client/java/query/PrepareStatement.java
@@ -87,6 +87,29 @@ public class PrepareStatement implements SerializableStatement {
         }
     }

+    /**
+     * Construct a {@link PrepareStatement} from a select-like {@link Statement} and give it a name.
+     *
+     * Note that passing a {@link PrepareStatement} or a {@link PreparedPayload} will reuse the
+     * {@link PrepareStatement#originalStatement() original statement} but use the given name.
+     *
+     * @param statement the {@link Statement} to prepare.
+     * @param preparedName the name to give to the prepared statement
+     * @return the prepared statement.
+     * @throws IllegalArgumentException when statement cannot be prepared.
+     */
+    public static PrepareStatement prepare(Statement statement, String preparedName) {
+        Statement original;
+        if (statement instanceof PrepareStatement) {
+            original = ((PrepareStatement) statement).originalStatement();
+        } else if (statement instanceof PreparedPayload) {
+            original = ((PreparedPayload) statement).originalStatement();
+        } else {
+            original = statement;
+        }
+        return new PrepareStatement(original, preparedName);
+    }
+
     /**
      * Construct a {@link PrepareStatement} from a statement in {@link String} format.
      * Statement shouldn't begin with "PREPARE", otherwise a syntax error may be returned by the server.
diff --git a/src/main/java/com/couchbase/client/java/query/PreparedQuery.java b/src/main/java/com/couchbase/client/java/query/PreparedQuery.java
index 72ddc88ea362166c5323d77b22f7faa8887fef19..d628c65ce39c46f8dddd9e621c65fb78a2deb29e 100644
--- a/src/main/java/com/couchbase/client/java/query/PreparedQuery.java
+++ b/src/main/java/com/couchbase/client/java/query/PreparedQuery.java
@@ -66,4 +66,16 @@ public class PreparedQuery extends ParametrizedQuery {
     public PreparedPayload statement() {
         return (PreparedPayload) super.statement();
     }
+
+    @Override
+    public JsonObject n1ql() {
+        JsonObject n1ql = super.n1ql();
+        String preparePrefix = "PREPARE " + statement().preparedName() + " FROM ";
+        String prepareFallback = statement().originalStatement().toString();
+        if (!prepareFallback.toLowerCase().startsWith("prepare ")) {
+            prepareFallback = preparePrefix + prepareFallback;
+        }
+        n1ql.put("statement", prepareFallback);
+        return n1ql;
+    }
 }
