diff --git a/src/test/java/com/couchbase/client/java/behavior/backpressure/BackpressureTests.java b/src/test/java/com/couchbase/client/java/behavior/backpressure/BackpressureTests.java
new file mode 100644
index 0000000000000000000000000000000000000000..793fc968e267383ce5416551f035e2d4662937f4
--- /dev/null
+++ b/src/test/java/com/couchbase/client/java/behavior/backpressure/BackpressureTests.java
@@ -0,0 +1,198 @@
+/*
+ * Copyright (C) 2015 Couchbase, Inc.
+ *
+ * Permission is hereby granted, free of charge, to any person obtaining a copy
+ * of this software and associated documentation files (the "Software"), to deal
+ * in the Software without restriction, including without limitation the rights
