index 0000000000000000000000000000000000000000..d01c5be6b07149ad85abdba4d0eccb59ab6709e6
--- /dev/null
+++ b/src/integration/java/com/couchbase/client/java/bucket/BucketManagerIndexManagementTests.java
@@ -0,0 +1,318 @@
+/*
