diff --git a/src/main/java/com/couchbase/client/java/query/util/IndexInfo.java b/src/main/java/com/couchbase/client/java/query/util/IndexInfo.java
new file mode 100644
index 0000000000000000000000000000000000000000..a2605225564502c887e09b3adad95abf30e33260
--- /dev/null
+++ b/src/main/java/com/couchbase/client/java/query/util/IndexInfo.java
@@ -0,0 +1,192 @@
+/**
+ * Copyright (C) 2015 Couchbase, Inc.
+ *
+ * Permission is hereby granted, free of charge, to any person obtaining a copy
+ * of this software and associated documentation files (the "Software"), to deal
+ * in the Software without restriction, including without limitation the rights
