+package com.couchbase.client.java.query;
+
+import com.couchbase.client.java.CouchbaseAsyncBucket;
+import com.couchbase.client.java.query.dsl.Expression;
+import com.couchbase.client.java.query.dsl.element.Element;
+import com.couchbase.client.java.query.dsl.path.AbstractPath;
+import com.couchbase.client.java.query.dsl.path.DefaultUpdateUsePath;
+import com.couchbase.client.java.query.dsl.path.UpdateUsePath;
+
+import static com.couchbase.client.java.query.dsl.Expression.x;
+
+public class Update {
+
+  private Update() {}
+
+  public static UpdateUsePath update(String bucket) {
+    return new DefaultUpdateUsePath(new UpdatePath(x(bucket)));
+  }
+
+  public static UpdateUsePath update(Expression bucket) {
+    return new DefaultUpdateUsePath(new UpdatePath(bucket));
+  }
+
+  public static UpdateUsePath updateCurrentBucket() {
+    return new DefaultUpdateUsePath(new UpdatePath(x(CouchbaseAsyncBucket.CURRENT_BUCKET_IDENTIFIER)));
+  }
+
+  private static class UpdatePath extends AbstractPath {
+    public UpdatePath(final Expression bucket) {
+      super(null);
+      element(new Element() {
+        @Override
+        public String export() {
+          return "UPDATE " + bucket.toString();
+        }
+      });
+    }
+  }
+
+}
diff --git a/src/main/java/com/couchbase/client/java/query/dsl/element/SetElement.java b/src/main/java/com/couchbase/client/java/query/dsl/element/SetElement.java
new file mode 100644
index 0000000000000000000000000000000000000000..51966c42948f0f90509f9c8a2ef9101004022e2e
--- /dev/null
+++ b/src/main/java/com/couchbase/client/java/query/dsl/element/SetElement.java
@@ -0,0 +1,36 @@
+package com.couchbase.client.java.query.dsl.element;
+
+import com.couchbase.client.java.query.dsl.Expression;
+
+public class SetElement implements Element {
+
+  private final Expression path;
+  private final Expression setFor;
+  private final SetPosition insert;
+  private final Expression value;
+
+  public SetElement(SetPosition insert, Expression path, Expression value, Expression setFor) {
+    this.path = path;
+    this.setFor = setFor;
+    this.insert = insert;
+    this.value = value;
+  }
+
+  @Override
+  public String export() {
+    String uf = setFor == null ? "" : " " + setFor.toString();
+    return insert.repr + path.toString() + " = " + value.toString() + uf;
+  }
+
+  public enum SetPosition {
+    INITIAL("SET "),
+    NOT_INITIAL(", ");
+
+    private final String repr;
+
+    SetPosition(String repr) {
+      this.repr = repr;
+    }
+  }
+
+}
