diff --git a/src/test/java/com/couchbase/client/java/query/dsl/DeleteDslTest.java b/src/test/java/com/couchbase/client/java/query/dsl/DeleteDslTest.java
new file mode 100644
index 0000000000000000000000000000000000000000..f2c6b6903eb59fe2770af11e2b023db703d816cc
--- /dev/null
+++ b/src/test/java/com/couchbase/client/java/query/dsl/DeleteDslTest.java
@@ -0,0 +1,135 @@
+/**
+ * Copyright (C) 2015 Couchbase, Inc.
+ *
+ * Permission is hereby granted, free of charge, to any person obtaining a copy
+ * of this software and associated documentation files (the "Software"), to deal
+ * in the Software without restriction, including without limitation the rights
