+ * IMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY,
+ * FITNESS FOR A PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE
+ * AUTHORS OR COPYRIGHT HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER
+ * LIABILITY, WHETHER IN AN ACTION OF CONTRACT, TORT OR OTHERWISE, ARISING
+ * FROM, OUT OF OR IN CONNECTION WITH THE SOFTWARE OR THE USE OR OTHER DEALING
+ * IN THE SOFTWARE.
+ */
+package com.couchbase.client.java.query.dsl;
+
+import com.couchbase.client.java.document.json.JsonArray;
+import com.couchbase.client.java.document.json.JsonObject;
+import com.couchbase.client.java.query.Insert;
+import com.couchbase.client.java.query.Statement;
+import com.couchbase.client.java.query.Upsert;
+import com.couchbase.client.java.query.dsl.path.DefaultInitialInsertPath;
+import com.couchbase.client.java.query.dsl.path.DefaultReturningPath;
+import org.junit.Test;
+
+import static com.couchbase.client.java.query.Select.select;
+import static com.couchbase.client.java.query.dsl.Expression.i;
+import static com.couchbase.client.java.query.dsl.Expression.s;
+import static com.couchbase.client.java.query.dsl.Expression.x;
+import static com.couchbase.client.java.query.dsl.functions.StringFunctions.upper;
+import static org.junit.Assert.assertEquals;
+
+/**
+ * Unit tests for the Insert Builder API.
+ *
+ * @author Michael Nitschinger
+ * @since 2.2.3
+ */
+public class InsertAndUpsertDslTest {
+
+  @Test
+  public void shouldConvertRegularReturning() {
+    Statement statement = new DefaultReturningPath(null).returning("foobar");
+    assertEquals("RETURNING foobar", statement.toString());
+  }
+
+  @Test
+  public void shouldConvertRawReturning() {
+    Statement statement = new DefaultReturningPath(null).returningRaw("foobar");
+    assertEquals("RETURNING RAW foobar", statement.toString());
+  }
+
+  @Test
+  public void shouldConvertElementReturning() {
+    Statement statement = new DefaultReturningPath(null).returningElement("foobar");
+    assertEquals("RETURNING ELEMENT foobar", statement.toString());
+
+    statement = new DefaultReturningPath(null).returningElement(upper("bla"));
+    assertEquals("RETURNING ELEMENT UPPER(bla)", statement.toString());
+  }
+
+  @Test
+  public void shouldConvertValues() {
+    Statement statement = new DefaultInitialInsertPath(null)
+      .values("fooid", JsonObject.empty());
+
+    assertEquals("VALUES (\"fooid\", {})", statement.toString());
+
+    statement = new DefaultInitialInsertPath(null)
+      .values("fooid", JsonObject.empty())
+      .values("barid", JsonObject.create().put("foo", true));
+
+    assertEquals(
+      "VALUES (\"fooid\", {}) , (\"barid\", {\"foo\":true})",
+      statement.toString()
+    );
+
+    statement = new DefaultInitialInsertPath(null)
+      .values(s("foo").concat(s("bar")), JsonArray.from(1, 2, 3, 4))
+      .values(upper(s("bla")), true);
+
+    assertEquals(
+      "VALUES (\"foo\" || \"bar\", [1,2,3,4]) , (UPPER(\"bla\"), TRUE)",
+      statement.toString()
+    );
+  }
+
+  @Test
+  public void shouldConvertValuesWithReturning() {
+    Statement statement = new DefaultInitialInsertPath(null)
+      .values("user", JsonObject.create().put("fname", "michael").put("age", 27))
+      .returning("fname");
+
+    assertEquals(
+      "VALUES (\"user\", {\"fname\":\"michael\",\"age\":27}) RETURNING fname",
+      statement.toString()
+    );
+  }
+
+  @Test
+  public void shouldConvertFullInsertIntoValues() {
+    Statement statement = Insert
+      .insertInto("default")
+      .values("user", JsonObject.create().put("fname", "michael").put("age", 27))
+      .values("doc2", true)
+      .returning("fname");
+
+    assertEquals(
+      "INSERT INTO default VALUES (\"user\", {\"fname\":\"michael\"," +
+        "\"age\":27}) , (\"doc2\", TRUE) RETURNING fname",
+      statement.toString()
+    );
+  }
+
+  @Test
+  public void shouldConvertFullInsertIntoSelect() {
+    Statement statement = Insert
+      .insertInto(i("beer-sample"))
+      .select("code", select("`beer-sample`.*").from(i("beer-sample")).limit(1));
+
+    assertEquals(
+      "INSERT INTO `beer-sample` (KEY code) SELECT `beer-sample`.* FROM `beer-sample` LIMIT 1",
+      statement.toString()
+    );
+
+    statement = Insert
+      .insertInto(i("beer-sample"))
+      .select(
+        "code",
+        x(JsonObject.create().put("c", "city").put("n", "name")),
+        select("`beer-sample`.*").from(i("beer-sample")).limit(1)
+      );
+
+    assertEquals(
+      "INSERT INTO `beer-sample` (KEY code, VALUE {\"n\":\"name\",\"c\":\"city\"}) SELECT " +
+        "`beer-sample`.* FROM `beer-sample` LIMIT 1",
+      statement.toString()
+    );
+  }
+
+
+  @Test
+  public void shouldConvertFullUpsertIntoValues() {
+    Statement statement = Upsert
+      .upsertInto("default")
+      .values("user", JsonObject.create().put("fname", "michael").put("age", 27))
+      .values("doc2", true)
+      .returning("fname");
+
+    assertEquals(
+      "UPSERT INTO default VALUES (\"user\", {\"fname\":\"michael\"," +
+        "\"age\":27}) , (\"doc2\", TRUE) RETURNING fname",
+      statement.toString()
+    );
+  }
+
+  @Test
+  public void shouldConvertFullUpsertIntoSelect() {
+    Statement statement = Upsert
+      .upsertInto(i("beer-sample"))
+      .select("code", select("`beer-sample`.*").from(i("beer-sample")).limit(1));
+
+    assertEquals(
+      "UPSERT INTO `beer-sample` (KEY code) SELECT `beer-sample`.* FROM `beer-sample` LIMIT 1",
+      statement.toString()
+    );
+
+    statement = Upsert
+      .upsertInto(i("beer-sample"))
+      .select(
+        "code",
+        x(JsonObject.create().put("c", "city").put("n", "name")),
+        select("`beer-sample`.*").from(i("beer-sample")).limit(1)
+      );
+
+    assertEquals(
+      "UPSERT INTO `beer-sample` (KEY code, VALUE {\"n\":\"name\",\"c\":\"city\"}) SELECT " +
+        "`beer-sample`.* FROM `beer-sample` LIMIT 1",
+      statement.toString()
+    );
+  }
+
+}
diff --git a/src/test/java/com/couchbase/client/java/query/dsl/MergeDslTest.java b/src/test/java/com/couchbase/client/java/query/dsl/MergeDslTest.java
new file mode 100644
index 0000000000000000000000000000000000000000..06255db615253417434395ba205d9c22a128d65b
--- /dev/null
+++ b/src/test/java/com/couchbase/client/java/query/dsl/MergeDslTest.java
@@ -0,0 +1,223 @@
+package com.couchbase.client.java.query.dsl;
+
+import com.couchbase.client.java.document.json.JsonObject;
+import com.couchbase.client.java.query.Merge;
+import com.couchbase.client.java.query.Statement;
+import com.couchbase.client.java.query.dsl.path.DefaultMergeDeletePath;
+import com.couchbase.client.java.query.dsl.path.DefaultMergeInsertPath;
+import com.couchbase.client.java.query.dsl.path.DefaultMergeKeyClausePath;
+import com.couchbase.client.java.query.dsl.path.DefaultMergeSourcePath;
+import com.couchbase.client.java.query.dsl.path.DefaultMergeUpdatePath;
+import com.couchbase.client.java.query.dsl.path.DefaultMutateLimitPath;
+import com.couchbase.client.java.query.dsl.path.DefaultReturningPath;
+import com.couchbase.client.java.query.dsl.path.Path;
+import org.junit.Test;
+
+import static com.couchbase.client.java.query.dsl.Expression.s;
+import static com.couchbase.client.java.query.dsl.Expression.x;
+import static com.couchbase.client.java.query.dsl.functions.StringFunctions.upper;
+import static org.junit.Assert.assertEquals;
+
+/**
+ * Unit tests for the Merge Builder API.
+ *
+ * @author Michael Nitschinger
+ * @since 2.2.3
+ */
+public class MergeDslTest {
+
+  @Test
+  public void shouldConvertRegularReturning() {
+    Statement statement = new DefaultReturningPath(null).returning("foobar");
+    assertEquals("RETURNING foobar", statement.toString());
+  }
+
+  @Test
+  public void shouldConvertRawReturning() {
+    Statement statement = new DefaultReturningPath(null).returningRaw("foobar");
+    assertEquals("RETURNING RAW foobar", statement.toString());
+  }
+
+  @Test
+  public void shouldConvertElementReturning() {
+    Statement statement = new DefaultReturningPath(null).returningElement("foobar");
+    assertEquals("RETURNING ELEMENT foobar", statement.toString());
+
+    statement = new DefaultReturningPath(null).returningElement(upper("bla"));
+    assertEquals("RETURNING ELEMENT UPPER(bla)", statement.toString());
+  }
+
+  @Test
+  public void shouldConvertLimit() {
+    Statement statement = new DefaultMutateLimitPath(null).limit(5);
+    assertEquals("LIMIT 5", statement.toString());
+  }
+
+  @Test
+  public void shouldConvertLimitWithReturning() {
+    Statement statement = new DefaultMutateLimitPath(null)
+      .limit(5)
+      .returning("foo");
+    assertEquals("LIMIT 5 RETURNING foo", statement.toString());
+  }
+
+  @Test
+  public void shouldConvertMergeInsert() {
+    Statement statement = new DefaultMergeInsertPath(null)
+      .whenNotMatchedThenInsert(x(JsonObject.create().put("foo", "bar")));
+    assertEquals("WHEN NOT MATCHED THEN INSERT {\"foo\":\"bar\"}", statement.toString());
+
+    statement = new DefaultMergeInsertPath(null)
+      .whenNotMatchedThenInsert(x(JsonObject.create().put("foo", "bar"))).where(x("a").gt(5));
+    assertEquals("WHEN NOT MATCHED THEN INSERT {\"foo\":\"bar\"} WHERE a > 5", statement.toString());
+  }
+
+  @Test
+  public void shouldConvertMergeInsertWithLimit() {
+    Statement statement = new DefaultMergeInsertPath(null)
+      .whenNotMatchedThenInsert(x(JsonObject.create().put("foo", "bar")))
+      .limit(5);
+    assertEquals("WHEN NOT MATCHED THEN INSERT {\"foo\":\"bar\"} LIMIT 5", statement.toString());
+  }
+
+  @Test
+  public void shouldConvertMergeDelete() {
+    Statement statement = new DefaultMergeDeletePath(null)
+      .whenMatchedThenDelete().where(x("a").eq(s("b")));
+    assertEquals("WHEN MATCHED THEN DELETE WHERE a = \"b\"", statement.toString());
+
+    statement = new DefaultMergeDeletePath(null)
+      .whenMatchedThenDelete();
+    assertEquals("WHEN MATCHED THEN DELETE", statement.toString());
+  }
+
+  @Test
+  public void shouldConvertMergeDeleteWithInsert() {
+    Statement statement = new DefaultMergeDeletePath(null)
+      .whenMatchedThenDelete().where(x("a").eq(s("b")))
+      .whenNotMatchedThenInsert(x(JsonObject.create().put("foo", "bar")));
+
+    assertEquals(
+      "WHEN MATCHED THEN DELETE WHERE a = \"b\" WHEN NOT MATCHED THEN INSERT {\"foo\":\"bar\"}",
+      statement.toString()
+    );
+  }
+
+  @Test
+  public void shouldConvertMergeUpdateWithSetAndUnset() {
+    Statement statement = new DefaultMergeUpdatePath(null)
+      .whenMatchedThenUpdate()
+      .set("foo", "bar")
+      .set("bar", 5);
+
+
+    assertEquals(
+      "WHEN MATCHED THEN UPDATE SET foo = \"bar\" , bar = 5",
+      statement.toString()
+    );
+
+    statement = new DefaultMergeUpdatePath(null)
+      .whenMatchedThenUpdate()
+      .unset("foo")
+      .unset("bar");
+
+    assertEquals(
+      "WHEN MATCHED THEN UPDATE UNSET foo , bar",
+      statement.toString()
+    );
+
+    statement = new DefaultMergeUpdatePath(null)
+      .whenMatchedThenUpdate()
+      .set("foo", "bar")
+      .unset("baz");
+
+    assertEquals(
+      "WHEN MATCHED THEN UPDATE SET foo = \"bar\" UNSET baz",
+      statement.toString()
+    );
+
+    statement = new DefaultMergeUpdatePath(null)
+      .whenMatchedThenUpdate()
+      .set("foo", "bar")
+      .set("bla", JsonObject.empty())
+      .unset("baz")
+      .unset("jup");
+
+    assertEquals(
+      "WHEN MATCHED THEN UPDATE SET foo = \"bar\" , bla = {} UNSET baz , jup",
+      statement.toString()
+    );
+  }
+
+  @Test
+  public void shouldConvertMergeKeyClause() {
+    Statement statement = new DefaultMergeKeyClausePath(null)
+      .onKey("o.productId");
+    assertEquals("ON KEY o.productId", statement.toString());
+
+    statement = new DefaultMergeKeyClausePath(null)
+      .onPrimaryKey("foobar");
+    assertEquals("ON PRIMARY KEY foobar", statement.toString());
+
+    statement = new DefaultMergeKeyClausePath(null)
+      .onKey("o.productId")
+      .whenMatchedThenUpdate()
+      .set("p.lastSaleDate", x("o.orderDate"));
+    assertEquals(
+      "ON KEY o.productId WHEN MATCHED THEN UPDATE SET p.lastSaleDate = o.orderDate",
+      statement.toString()
+    );
+  }
+
+  @Test
+  public void shouldConvertMergeSource() {
+    Path path = new DefaultMergeSourcePath(null)
+      .using(x("orders").as("o"));
+    assertEquals("USING orders AS o", path.toString());
+
+    Statement statement = new DefaultMergeSourcePath(null)
+      .using(x("orders").as("o"))
+      .onKey("o.productId");
+    assertEquals("USING orders AS o ON KEY o.productId", statement.toString());
+  }
+
+  @Test
+  public void shouldConvertFullMerge() {
+    Statement statement = Merge
+      .mergeInto("product p")
+      .using("orders o")
+      .onKey("o.productId")
+      .whenMatchedThenUpdate().set("p.lastSaleDate", x("o.orderDate"))
+      .whenMatchedThenDelete().where(x("p.inventoryCount").lte(0));
+
+    assertEquals(
+      "MERGE INTO product p " +
+        "USING orders o " +
+        "ON KEY o.productId " +
+        "WHEN MATCHED THEN UPDATE SET p.lastSaleDate = o.orderDate " +
+        "WHEN MATCHED THEN DELETE WHERE p.inventoryCount <= 0",
+      statement.toString()
+    );
+
+    statement = Merge
+      .mergeInto("all_empts a")
+      .using(x("emps_deptb").as("b"))
+      .onKey("b.empId")
+      .whenMatchedThenUpdate()
+        .set("a.depts", x("a.depts").add(1))
+        .set("a.title", x("b.title").concat(s(", ")).concat("b.title"))
+      .whenNotMatchedThenInsert(
+        x("{ \"name\": b.name, \"title\": b.title, \"depts\": b.depts, \"empId\": " +
+          "b.empId, \"dob\": b.dob }")
+      );
+
+    assertEquals(
+      "MERGE INTO all_empts a USING emps_deptb AS b ON KEY b.empId " +
+        "WHEN MATCHED THEN UPDATE SET a.depts = a.depts + 1 , " +
+        "a.title = b.title || \", \" || b.title " +
+        "WHEN NOT MATCHED THEN INSERT { \"name\": b.name, \"title\": b.title, \"depts\": " +
+        "b.depts, \"empId\": b.empId, \"dob\": b.dob }",
+      statement.toString()
+    );
+  }
+}
diff --git a/src/test/java/com/couchbase/client/java/query/dsl/UpdateDslTest.java b/src/test/java/com/couchbase/client/java/query/dsl/UpdateDslTest.java
new file mode 100644
index 0000000000000000000000000000000000000000..5b0dc34f23b3d8a559b9a6db30b23f92d7ccb074
--- /dev/null
+++ b/src/test/java/com/couchbase/client/java/query/dsl/UpdateDslTest.java
@@ -0,0 +1,178 @@
+package com.couchbase.client.java.query.dsl;
+
+import com.couchbase.client.java.document.json.JsonObject;
+import com.couchbase.client.java.query.Statement;
+import com.couchbase.client.java.query.Update;
+import com.couchbase.client.java.query.dsl.path.DefaultMutateLimitPath;
+import com.couchbase.client.java.query.dsl.path.DefaultMutateWherePath;
+import com.couchbase.client.java.query.dsl.path.DefaultReturningPath;
+import com.couchbase.client.java.query.dsl.path.DefaultUpdateSetOrUnsetPath;
+import com.couchbase.client.java.query.dsl.path.DefaultUpdateUsePath;
+import org.junit.Test;
+
+import static com.couchbase.client.java.query.dsl.Expression.s;
+import static com.couchbase.client.java.query.dsl.Expression.x;
+import static com.couchbase.client.java.query.dsl.functions.StringFunctions.upper;
+import static org.junit.Assert.assertEquals;
+
+/**
+ * Unit tests for the Update Builder API.
+ *
+ * @author Michael Nitschinger
+ * @since 2.2.3
+ */
+public class UpdateDslTest {
+
+  @Test
+  public void shouldConvertRegularReturning() {
+    Statement statement = new DefaultReturningPath(null).returning("foobar");
+    assertEquals("RETURNING foobar", statement.toString());
+  }
+
+  @Test
+  public void shouldConvertRawReturning() {
+    Statement statement = new DefaultReturningPath(null).returningRaw("foobar");
+    assertEquals("RETURNING RAW foobar", statement.toString());
+  }
+
+  @Test
+  public void shouldConvertElementReturning() {
+    Statement statement = new DefaultReturningPath(null).returningElement("foobar");
+    assertEquals("RETURNING ELEMENT foobar", statement.toString());
+
+    statement = new DefaultReturningPath(null).returningElement(upper("bla"));
+    assertEquals("RETURNING ELEMENT UPPER(bla)", statement.toString());
+  }
+
+  @Test
+  public void shouldConvertLimit() {
+    Statement statement = new DefaultMutateLimitPath(null).limit(5);
+    assertEquals("LIMIT 5", statement.toString());
+  }
+
+  @Test
+  public void shouldConvertLimitWithReturning() {
+    Statement statement = new DefaultMutateLimitPath(null)
+      .limit(5)
+      .returning("foo");
+    assertEquals("LIMIT 5 RETURNING foo", statement.toString());
+  }
+
+  @Test
+  public void shouldConvertWhere() {
+    Statement statement = new DefaultMutateWherePath(null)
+      .where("a = b");
+    assertEquals("WHERE a = b", statement.toString());
+  }
+
+  @Test
+  public void shouldConvertWhereWithLimit() {
+    Statement statement = new DefaultMutateWherePath(null)
+      .where(x("foo").gt(5))
+      .limit(8);
+    assertEquals("WHERE foo > 5 LIMIT 8", statement.toString());
+  }
+
+  @Test
+  public void shouldConvertUnset() {
+    Statement statement = new DefaultUpdateSetOrUnsetPath(null)
+      .unset("foo")
+      .unset("bar", x("FOR a IN b END"));
+
+    assertEquals("UNSET foo , bar FOR a IN b END", statement.toString());
+
+    statement = new DefaultUpdateSetOrUnsetPath(null).unset("foo");
+    assertEquals("UNSET foo", statement.toString());
+  }
+
+  @Test
+  public void shouldConvertSet() {
+    Statement statement = new DefaultUpdateSetOrUnsetPath(null)
+      .set("foo", s("bar"))
+      .set("what", true);
+
+    assertEquals("SET foo = \"bar\" , what = TRUE", statement.toString());
+
+    statement = new DefaultUpdateSetOrUnsetPath(null)
+      .set("foo", s("bar"))
+      .where(x("a").gt(5));
+
+    assertEquals("SET foo = \"bar\" WHERE a > 5", statement.toString());
+
+    statement = new DefaultUpdateSetOrUnsetPath(null)
+      .set("foo", JsonObject.create().put("a", "b"))
+      .where(x("a").gt(5));
+
+    assertEquals("SET foo = {\"a\":\"b\"} WHERE a > 5", statement.toString());
+  }
+
+  @Test
+  public void shouldConvertSetAndUnset() {
+    Statement statement = new DefaultUpdateSetOrUnsetPath(null)
+      .set("a", JsonObject.create().put("x", "y"))
+      .set("e", true)
+      .unset("b")
+      .unset("c")
+      .where(x("a").gt(5));
+
+    assertEquals("SET a = {\"x\":\"y\"} , e = TRUE UNSET b , c WHERE a > 5", statement.toString());
+  }
+
+  @Test
+  public void shouldConvertUse() {
+    Statement statement = new DefaultUpdateUsePath(null)
+      .useKeysValues("foo", "bar", "baz");
+    assertEquals("USE KEYS [\"foo\",\"bar\",\"baz\"]", statement.toString());
+  }
+
+  @Test
+  public void shouldConvertUseWithSetAndUnset() {
+    Statement statement = new DefaultUpdateUsePath(null)
+      .useKeysValues("foo", "bar", "baz")
+      .set("e", true)
+      .unset("b")
+      .where(x("a").gt(5));
+
+    assertEquals(
+      "USE KEYS [\"foo\",\"bar\",\"baz\"] SET e = TRUE UNSET b WHERE a > 5",
+      statement.toString()
+    );
+  }
+
+  @Test
+  public void shouldConvertFullUpdate() {
+    Statement statement = Update
+      .update("product")
+      .useKeysValues("odwalla-juice1")
+      .set("type", "product-juice")
+      .returning("product.type");
+
+    assertEquals(
+      "UPDATE product USE KEYS \"odwalla-juice1\" SET type = \"product-juice\" RETURNING product.type",
+      statement.toString()
+    );
+
+    statement = Update
+      .update("product")
+      .useKeysValues("odwalla-juice1")
+      .unset("type")
+      .returning("product.*");
+
+    assertEquals(
+      "UPDATE product USE KEYS \"odwalla-juice1\" UNSET type RETURNING product.*",
+      statement.toString()
+    );
+
+    statement = Update
+      .update("tutorial t")
+      .useKeysValues("dave")
+      .unset("c.gender", x("FOR c IN children END"))
+      .returning("t");
+
+    assertEquals(
+      "UPDATE tutorial t USE KEYS \"dave\" UNSET c.gender FOR c IN children END RETURNING t",
+      statement.toString()
+    );
+  }
+
+}

diff --git a/src/integration/java/com/couchbase/client/java/SubDocumentTest.java b/src/integration/java/com/couchbase/client/java/SubDocumentTest.java
new file mode 100644
