+
+        public Builder inclusiveMin(boolean inclusiveMin) {
+            this.inclusiveMin = inclusiveMin;
+            return this;
+        }
+
+        public Builder inclusiveMax(boolean inclusiveMax) {
+            this.inclusiveMax = inclusiveMax;
+            return this;
