diff --git a/src/main/java/com/couchbase/client/java/query/dsl/clause/UpdateForClause.java b/src/main/java/com/couchbase/client/java/query/dsl/clause/UpdateForClause.java
new file mode 100644
index 0000000000000000000000000000000000000000..57c4ccfd0185dcf893a8ce9aed060856b963c604
--- /dev/null
+++ b/src/main/java/com/couchbase/client/java/query/dsl/clause/UpdateForClause.java
@@ -0,0 +1,126 @@
+/*
