+    private static void releaseAll(List<ByteBuf> byteBufs) {
+        for (ByteBuf byteBuf : byteBufs) {
+            if (byteBuf != null && byteBuf.refCnt() > 0) {
+                byteBuf.release();
+            }
+        }
+    }
