diff --git a/src/main/java/com/couchbase/client/java/document/subdoc/DocumentFragment.java b/src/main/java/com/couchbase/client/java/document/subdoc/DocumentFragment.java
new file mode 100644
index 0000000000000000000000000000000000000000..7d46be817a26529b622d3250d8c84d36fd906847
--- /dev/null
+++ b/src/main/java/com/couchbase/client/java/document/subdoc/DocumentFragment.java
@@ -0,0 +1,257 @@
+/*
+ * Copyright (C) 2016 Couchbase, Inc.
+ *
+ * Permission is hereby granted, free of charge, to any person obtaining a copy
+ * of this software and associated documentation files (the "Software"), to deal
+ * in the Software without restriction, including without limitation the rights
