new file mode 100644
index 0000000000000000000000000000000000000000..b182b089428e641f9e8a612f9e9f2b1c22cddf06
--- /dev/null
+++ b/src/main/java/com/couchbase/client/java/error/subdoc/MultiMutationException.java
@@ -0,0 +1,84 @@
+/*
