+
+    @Override
+    public WildcardQuery boost(double boost) {
+        super.boost(boost);
+        return this;
+    }
+
+    @Override
+    protected void injectParams(JsonObject input) {
+        if (field != null) {
+            input.put("field", field);
+        }
+        input.put("wildcard", wildcard);
+    }
+}
