diff --git a/src/test/java/com/couchbase/client/java/fts/queries/TermQueryTest.java b/src/test/java/com/couchbase/client/java/fts/queries/TermQueryTest.java
new file mode 100644
index 0000000000000000000000000000000000000000..06ad1ce2c80261084c97bd3fa1f46b5fc640fc7b
--- /dev/null
+++ b/src/test/java/com/couchbase/client/java/fts/queries/TermQueryTest.java
@@ -0,0 +1,89 @@
+/*
+ * Copyright (c) 2016 Couchbase, Inc.
+ *
+ * Licensed under the Apache License, Version 2.0 (the "License");
+ * you may not use this file except in compliance with the License.
+ * You may obtain a copy of the License at
+ *
+ *    http://www.apache.org/licenses/LICENSE-2.0
+ *
+ * Unless required by applicable law or agreed to in writing, software
+ * distributed under the License is distributed on an "AS IS" BASIS,
+ * WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.
+ * See the License for the specific language governing permissions and
+ * limitations under the License.
+ */
+package com.couchbase.client.java.fts.queries;
+
+import static org.junit.Assert.assertEquals;
+
+import com.couchbase.client.java.document.json.JsonArray;
+import com.couchbase.client.java.document.json.JsonObject;
+import com.couchbase.client.java.fts.SearchParams;
+import com.couchbase.client.java.fts.SearchQuery;
+import org.junit.Test;
+
+public class TermQueryTest {
+
+    @Test
+    public void shouldExportTermQuery() {
+        TermQuery query = SearchQuery.term("salty");
+        JsonObject expected = JsonObject.create()
+            .put("query", JsonObject.create().put("term", "salty"));
+        assertEquals(expected, query.export());
+    }
+
+    @Test
+    public void shouldOmitPrefixLengthWhenNoFuzziness() {
+        TermQuery query = SearchQuery.term("salty", SearchParams.build().limit(10))
+            .boost(1.5)
+            .field("field")
+            .prefixLength(12);
+
+        JsonObject expected = JsonObject.create()
+            .put("query", JsonObject.create()
+                .put("term", "salty")
+                .put("boost", 1.5)
+                .put("field", "field")) //no prefix_length
+            .put("size", 10);
+        assertEquals(expected, query.export());
+    }
+
+    @Test
+    public void shouldOmitPrefixLengthUnderOne() {
+        TermQuery query = SearchQuery.term("salty", SearchParams.build().limit(10))
+            .boost(1.5)
+            .field("field")
+            .fuzziness(23)
+            .prefixLength(-1);
+
+        JsonObject expected = JsonObject.create()
+            .put("query", JsonObject.create()
+                .put("term", "salty")
+                .put("boost", 1.5)
+                .put("field", "field")
+                .put("fuzziness", 23))
+            .put("size", 10);
+        assertEquals(expected, query.export());
+    }
+
+    @Test
+    public void shouldExportTermQueryWithAllOptions() {
+        TermQuery query = SearchQuery.term("salty", SearchParams.build().limit(10))
+            .boost(1.5)
+            .field("field")
+            .fuzziness(23)
+            .prefixLength(12);
+
+        JsonObject expected = JsonObject.create()
+            .put("query", JsonObject.create()
+                .put("term", "salty")
+                .put("boost", 1.5)
+                .put("field", "field")
+                .put("fuzziness", 23)
+                .put("prefix_length", 12))
+            .put("size", 10);
+        assertEquals(expected, query.export());
+    }
+
+}
