     String name();
     String field();
+
+    /**
+     * @return the total number of *valued* facet results. Total = {@link #other()} + terms (but doesn't include
+     * {@link #missing()}).
+     */
     long total();
+
+    /**
+     * @return the number of results that couldn't be faceted, missing the adequate value. Not matter how many more
