+                        fragment = new ArrayList<String>(fragmentJson.size());
+                        for (int i = 0; i < fragmentJson.size(); i++) {
+                            fragment.add(fragmentJson.getString(i));
+                        }
+                    } else {
+                        fragment = Collections.emptyList();
+                    }
+                    fragments.put(field, fragment);
