diff --git a/src/main/java/com/couchbase/client/java/fts/result/SearchQueryResult.java b/src/main/java/com/couchbase/client/java/fts/result/SearchQueryResult.java
index bdc76ee789c135c0a0a3f26e179658094ae96cc3..48dc4e79119cb892726363d73e1debec5ded3070 100644
--- a/src/main/java/com/couchbase/client/java/fts/result/SearchQueryResult.java
+++ b/src/main/java/com/couchbase/client/java/fts/result/SearchQueryResult.java
@@ -18,16 +18,66 @@ package com.couchbase.client.java.fts.result;
 import java.util.List;
 import java.util.Map;

+import com.couchbase.client.core.annotations.InterfaceAudience;
+import com.couchbase.client.core.annotations.InterfaceStability;
+import com.couchbase.client.java.document.json.JsonObject;
+import com.couchbase.client.java.fts.SearchParams;
+import com.couchbase.client.java.fts.facet.SearchFacet;
 import com.couchbase.client.java.fts.result.facets.FacetResult;
+import rx.exceptions.CompositeException;

+/**
+ * The main interface for FTS query results.
+ *
+ * @author Simon Baslé
+ * @author Michael Nitschinger
+ * @since 2.3.0
+ */
+@InterfaceStability.Experimental
+@InterfaceAudience.Public
 public interface SearchQueryResult {

+    /**
+     * The {@link SearchStatus} allows to check if the request was a full success ({@link SearchStatus#isSuccess()})
+     * and gives more details about status for each queried index.
+     */
     SearchStatus status();

+    /**
+     * The list of FTS result rows, or "hits", for the FTS query. This method always returns
+     * a list, including when an execution error (eg. partial results) occurred.
+     *
+     * @see #hitsOrFail() for a variant that throws an exception whenever execution errors have occurred.
+     * @see #errors() to get a list of execution errors in JSON form.
+     */
     List<SearchQueryRow> hits();
+
+    /**
+     * The list of FTS result rows, or "hits", for the FTS query. In case of an execution error
+     * (eg. partial results), a {@link CompositeException} is thrown instead.
+     *
+     * @see #hits() for a variant that lists partial results instead of throwing the exception.
+     * @see #errors() to get a list of execution errors in JSON form.
+     */
     List<SearchQueryRow> hitsOrFail();
+
+    /**
+     * When an execution error happens (including partial results), this method returns a {@link List} of
+     * the error(s) in {@link JsonObject JSON format}.
+     *
+     * @see #hits() to get results, including partial results (rather than throwing an exception).
+     * @see #hitsOrFail() to get only full results, but throwing an exception whenever execution errors have occurred.
+     */
     List<String> errors();
+
+    /**
+     * If one or more facet were requested via the {@link SearchParams#addFacets(SearchFacet...)} method when querying,
+     * contains the result of each facet. The map keys are the names given to each requested facet.
+     */
     Map<String, FacetResult> facets();

+    /**
+     * Provides a {@link SearchMetrics} object giving statistics on the request like number of hits, total time taken...
+     */
     SearchMetrics metrics();
 }
diff --git a/src/main/java/com/couchbase/client/java/fts/result/SearchQueryRow.java b/src/main/java/com/couchbase/client/java/fts/result/SearchQueryRow.java
index 5b45c7e076c1dbb1d279d026ff55f1f30d41e87b..2a4ab7b16e752d84a4bf37089ebaeae031c401ba 100644
--- a/src/main/java/com/couchbase/client/java/fts/result/SearchQueryRow.java
