+ * WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.
+ * See the License for the specific language governing permissions and
+ * limitations under the License.
+ */
+package com.couchbase.client.java.fts.queries;
+
+import com.couchbase.client.core.annotations.InterfaceAudience;
+import com.couchbase.client.core.annotations.InterfaceStability;
+import com.couchbase.client.java.document.json.JsonObject;
+
+/**
+ * A FTS query that matches a given term, applying further processing to it
+ * like analyzers, stemming and even {@link #fuzziness(int) fuzziness}.
+ *
+ * @author Simon Baslé
+ * @author Michael Nitschinger
+ * @since 2.3.0
+ */
+@InterfaceStability.Experimental
+@InterfaceAudience.Public
+public class MatchQuery extends AbstractFtsQuery {
+
+    private final String match;
+    private String field;
+    private String analyzer;
+    private Integer prefixLength;
+    private Integer fuzziness;
+
+    public MatchQuery(String match) {
+        super();
+        this.match = match;
+    }
+
+    @Override
+    public MatchQuery boost(double boost) {
+        super.boost(boost);
+        return this;
+    }
+
+    public MatchQuery field(String field) {
+        this.field = field;
+        return this;
+    }
+
+    public MatchQuery analyzer(String analyzer) {
+        this.analyzer = analyzer;
+        return this;
+    }
+
+    public MatchQuery prefixLength(int prefixLength) {
+        this.prefixLength = prefixLength;
+        return this;
+    }
+
+    public MatchQuery fuzziness(int fuzziness) {
+        this.fuzziness = fuzziness;
+        return this;
+    }
+
+    @Override
+    protected void injectParams(JsonObject input) {
+        input.put("match", match);
+        if (field != null) {
+            input.put("field", field);
+        }
+        if (analyzer != null) {
+            input.put("analyzer", analyzer);
+        }
+        if (prefixLength != null) {
+            input.put("prefix_length", prefixLength);
+        }
+        if (fuzziness != null) {
+            input.put("fuzziness", fuzziness);
+        }
+    }
+}
diff --git a/src/main/java/com/couchbase/client/java/fts/queries/NumericRangeQuery.java b/src/main/java/com/couchbase/client/java/fts/queries/NumericRangeQuery.java
new file mode 100644
index 0000000000000000000000000000000000000000..2395ba4dc36e3797fa881b6e112d954fdda4580f
--- /dev/null
+++ b/src/main/java/com/couchbase/client/java/fts/queries/NumericRangeQuery.java
@@ -0,0 +1,116 @@
+/*
