diff --git a/src/test/java/com/couchbase/client/java/MutationStateTest.java b/src/test/java/com/couchbase/client/java/MutationStateTest.java
new file mode 100644
index 0000000000000000000000000000000000000000..f1257ccfa2850f81b173acd30ace7e359f38265b
--- /dev/null
+++ b/src/test/java/com/couchbase/client/java/MutationStateTest.java
@@ -0,0 +1,280 @@
+/*
+ * Copyright (c) 2016 Couchbase, Inc.
+ *
+ * Licensed under the Apache License, Version 2.0 (the "License");
