new file mode 100644
index 0000000000000000000000000000000000000000..5b3bb61ee6ff5d9020c3bdae1e17662af49a9efd
--- /dev/null
+++ b/src/main/java/com/couchbase/client/java/MutationState.java
@@ -0,0 +1,166 @@
+/**
