+                .serverSideTimeout(3, TimeUnit.MILLISECONDS);
+
+        SearchQueryResult result = ctx.bucket().query(query);
+
+        assertThat(result.status().isSuccess()).isFalse();
+        catchException(result).hitsOrFail();
