diff --git a/src/integration/java/com/couchbase/client/java/N1qlClusterLevelTest.java b/src/integration/java/com/couchbase/client/java/N1qlClusterLevelTest.java
new file mode 100644
index 0000000000000000000000000000000000000000..7a11a26cafe176dbd3d2a7e68cfd47c2c3f8b1ef
--- /dev/null
+++ b/src/integration/java/com/couchbase/client/java/N1qlClusterLevelTest.java
@@ -0,0 +1,201 @@
+/*
+ * Copyright (c) 2016 Couchbase, Inc.
+ *
+ * Licensed under the Apache License, Version 2.0 (the "License");
+ * you may not use this file except in compliance with the License.
+ * You may obtain a copy of the License at
+ *
