diff --git a/src/main/java/com/couchbase/client/java/query/core/Criteria.java b/src/main/java/com/couchbase/client/java/query/core/Criteria.java
new file mode 100644
index 0000000000000000000000000000000000000000..61ca35477466a61daa2d2b9bf1ae788bb4922b7f
--- /dev/null
+++ b/src/main/java/com/couchbase/client/java/query/core/Criteria.java
@@ -0,0 +1,146 @@
+/*
+ * Copyright (c) 2016 Couchbase, Inc.
+ *
+ * Licensed under the Apache License, Version 2.0 (the "License");
+ * you may not use this file except in compliance with the License.
+ * You may obtain a copy of the License at
+ *
+ *    http://www.apache.org/licenses/LICENSE-2.0
