+        assertEquals("bar", iterator.previous()); //at "bar"
+        iterator.remove(); //-bar
+        assertEquals("foo", iterator.previous()); //at "foo"
+        iterator.remove(); //-foo
+        assertEquals("baz", iterator.next()); //at "baz"
+        iterator.remove(); //-baz
+
+        assertEquals(1, list.size());
+        assertEquals("keep", list.get(0));
+    }
