+        return new CouchbaseListIterator(index);
+    }
+
+    @Override
+    public void clear() {
+        //optimized version over AbstractList's (which iterates on all and remove)
+        bucket.upsert(JsonArrayDocument.create(id, JsonArray.empty()));
+    }
