+            String idx = "[" + index + "]";
+            try {
+                DocumentFragment<Mutation> updated = bucket.mutateIn(id).remove(idx).withCas(this.cas).execute();
+                //update the cas so that several removes in a row can work
+                this.cas = updated.cas();
