+
+        try {
+            CouchbaseArraySet<Object> set = new CouchbaseArraySet<Object>(uuid, bucket, initial);
+        } catch (ClassCastException e) {
+            assertTrue(e.getMessage().contains("CouchbaseArraySet"));
+            //success
+        }
+    }
+
+    @Test
