diff --git a/src/test/java/com/couchbase/client/java/util/OnSubscribeDeferAndWatchTest.java b/src/test/java/com/couchbase/client/java/util/OnSubscribeDeferAndWatchTest.java
new file mode 100644
index 0000000000000000000000000000000000000000..234d554a50f595f59afe9dabf788d85e0529d366
--- /dev/null
+++ b/src/test/java/com/couchbase/client/java/util/OnSubscribeDeferAndWatchTest.java
@@ -0,0 +1,119 @@
+/*
