+public class ConnectionString {
+
+    public static final String DEFAULT_SCHEME = "couchbase://";
+
+    private final Scheme scheme;
+    private final List<InetSocketAddress> hosts;
+    private final Map<String, String> params;
+
+    protected ConnectionString(final String input) {
+        this.scheme = parseScheme(input);
+        this.hosts = parseHosts(input);
+        this.params = parseParams(input);
+    }
+
+    public static ConnectionString create(final String input) {
+        return new ConnectionString(input);
+    }
+
+    public static ConnectionString fromHostnames(final List<String> hostnames) {
+        StringBuilder sb = new StringBuilder(DEFAULT_SCHEME);
+        for (int i = 0; i < hostnames.size(); i++) {
+            sb.append(hostnames.get(i));
+            if (i < hostnames.size()-1) {
+                sb.append(",");
+            }
+        }
+        return create(sb.toString());
+    }
+
+    static Scheme parseScheme(final String input) {
+        if (input.startsWith("couchbase://")) {
+            return Scheme.COUCHBASE;
+        } else if (input.startsWith("couchbases://")) {
+            return Scheme.COUCHBASES;
+        } else if (input.startsWith("http://")) {
+            return Scheme.HTTP;
+        } else {
+            throw new CouchbaseException("Could not parse Scheme of connection string: " + input);
+        }
+    }
+
+    static List<InetSocketAddress> parseHosts(final String input) {
+        String schemeRemoved = input.replaceAll("\\w+://", "");
+        String paramsRemoved = schemeRemoved.replaceAll("\\?.*", "");
+        String[] splitted = paramsRemoved.split(",");
+
+        List<InetSocketAddress> hosts = new ArrayList<InetSocketAddress>();
+        for (int i = 0; i < splitted.length; i++) {
+            if (splitted[i] == null || splitted[i].isEmpty()) {
+                continue;
+            }
+            String[] parts = splitted[i].split(":");
+            if (parts.length == 1) {
+                hosts.add(InetSocketAddress.createUnresolved(parts[0], 0));
+            } else {
+                hosts.add(InetSocketAddress.createUnresolved(parts[0], Integer.parseInt(parts[1])));
+            }
+        }
+        return hosts;
+    }
+
+    static Map<String, String> parseParams(final String input) {
+        try {
+            String[] parts = input.split("\\?");
+            Map<String, String> params = new HashMap<String, String>();
+            if (parts.length > 1) {
+                String found = parts[1];
+                String[] exploded = found.split("&");
+                for (int i = 0; i < exploded.length; i++) {
+                    String[] pair = exploded[i].split("=");
+                    params.put(pair[0], pair[1]);
+                }
+            }
+            return params;
+        } catch(Exception ex) {
+            throw new CouchbaseException("Could not parse Params of connection string: " + input, ex);
+        }
+    }
+
+    public Scheme scheme() {
+        return scheme;
+    }
+
+    public List<InetSocketAddress> hosts() {
+        return hosts;
+    }
+
+    public Map<String, String> params() {
+        return params;
+    }
+
+    public enum Scheme {
+        HTTP,
+        COUCHBASE,
+        COUCHBASES
+    }
+
+    @Override
+    public String toString() {
+        final StringBuilder sb = new StringBuilder("ConnectionString{");
+        sb.append("scheme=").append(scheme);
+        sb.append(", hosts=").append(hosts);
+        sb.append(", params=").append(params);
+        sb.append('}');
+        return sb.toString();
+    }
+}
diff --git a/src/test/java/com/couchbase/client/java/ConnectionStringTest.java b/src/test/java/com/couchbase/client/java/ConnectionStringTest.java
new file mode 100644
index 0000000000000000000000000000000000000000..fa80b174cf79e94ac04761faccc8bd56aa23c01a
--- /dev/null
+++ b/src/test/java/com/couchbase/client/java/ConnectionStringTest.java
@@ -0,0 +1,102 @@
+/*
+ * Copyright (c) 2016 Couchbase, Inc.
+ *
+ * Licensed under the Apache License, Version 2.0 (the "License");
+ * you may not use this file except in compliance with the License.
+ * You may obtain a copy of the License at
+ *
+ *    http://www.apache.org/licenses/LICENSE-2.0
+ *
+ * Unless required by applicable law or agreed to in writing, software
+ * distributed under the License is distributed on an "AS IS" BASIS,
+ * WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.
+ * See the License for the specific language governing permissions and
+ * limitations under the License.
+ */
+package com.couchbase.client.java;
+
+import com.couchbase.client.core.CouchbaseException;
+import org.junit.Test;
+
+import static org.junit.Assert.assertEquals;
+import static org.junit.Assert.assertTrue;
+
+public class ConnectionStringTest {
+
+    @Test
+    public void shouldParseValidSchemes() {
+        ConnectionString parsed = ConnectionString.create("couchbase://");
+        assertEquals(ConnectionString.Scheme.COUCHBASE, parsed.scheme());
+        assertTrue(parsed.hosts().isEmpty());
+        assertTrue(parsed.params().isEmpty());
+
+        parsed = ConnectionString.create("couchbases://");
+        assertEquals(ConnectionString.Scheme.COUCHBASES, parsed.scheme());
+        assertTrue(parsed.hosts().isEmpty());
+        assertTrue(parsed.params().isEmpty());
+
+        parsed = ConnectionString.create("http://");
+        assertEquals(ConnectionString.Scheme.HTTP, parsed.scheme());
+        assertTrue(parsed.hosts().isEmpty());
+        assertTrue(parsed.params().isEmpty());
+    }
+
+    @Test(expected = CouchbaseException.class)
+    public void shouldFailOnInvalidScheme() {
+        ConnectionString.create("invalid://");
+    }
+
+    @Test
+    public void shouldParseHostList() {
+        ConnectionString parsed = ConnectionString.create("couchbase://localhost");
+        assertEquals(ConnectionString.Scheme.COUCHBASE, parsed.scheme());
+        assertTrue(parsed.params().isEmpty());
+        assertEquals(1, parsed.hosts().size());
+        assertEquals("localhost", parsed.hosts().get(0).getHostName());
+        assertEquals(0, parsed.hosts().get(0).getPort());
+
+        parsed = ConnectionString.create("couchbase://localhost:1234");
+        assertEquals(ConnectionString.Scheme.COUCHBASE, parsed.scheme());
+        assertTrue(parsed.params().isEmpty());
+        assertEquals(1, parsed.hosts().size());
+        assertEquals("localhost", parsed.hosts().get(0).getHostName());
+        assertEquals(1234, parsed.hosts().get(0).getPort());
+
+        parsed = ConnectionString.create("couchbase://foo:1234,bar:5678");
+        assertEquals(ConnectionString.Scheme.COUCHBASE, parsed.scheme());
+        assertTrue(parsed.params().isEmpty());
+        assertEquals(2, parsed.hosts().size());
+        assertEquals("foo", parsed.hosts().get(0).getHostName());
+        assertEquals(1234, parsed.hosts().get(0).getPort());
+        assertEquals("bar", parsed.hosts().get(1).getHostName());
+        assertEquals(5678, parsed.hosts().get(1).getPort());
+
+        parsed = ConnectionString.create("couchbase://foo,bar:5678,baz");
+        assertEquals(ConnectionString.Scheme.COUCHBASE, parsed.scheme());
+        assertTrue(parsed.params().isEmpty());
+        assertEquals(3, parsed.hosts().size());
+        assertEquals("foo", parsed.hosts().get(0).getHostName());
+        assertEquals(0, parsed.hosts().get(0).getPort());
+        assertEquals("bar", parsed.hosts().get(1).getHostName());
+        assertEquals(5678, parsed.hosts().get(1).getPort());
+        assertEquals("baz", parsed.hosts().get(2).getHostName());
+        assertEquals(0, parsed.hosts().get(2).getPort());
+    }
+
+    @Test
+    public void shouldParseParams() {
+        ConnectionString parsed = ConnectionString.create("couchbase://localhost?foo=bar");
+        assertEquals(ConnectionString.Scheme.COUCHBASE, parsed.scheme());
+        assertEquals(1, parsed.hosts().size());
+        assertEquals(1, parsed.params().size());
+        assertEquals("bar", parsed.params().get("foo"));
+
+        parsed = ConnectionString.create("couchbase://localhost?foo=bar&setting=true");
+        assertEquals(ConnectionString.Scheme.COUCHBASE, parsed.scheme());
+        assertEquals(1, parsed.hosts().size());
+        assertEquals(2, parsed.params().size());
+        assertEquals("bar", parsed.params().get("foo"));
+        assertEquals("true", parsed.params().get("setting"));
+    }
+
+}
