new file mode 100644
index 0000000000000000000000000000000000000000..978b17f32351196705f19ae6f5faf0674020b6dc
--- /dev/null
+++ b/src/integration/java/com/couchbase/client/java/SubdocumentExtendedAttributesTest.java
@@ -0,0 +1,297 @@
+/*
