diff --git a/src/integration/java/com/couchbase/client/java/auth/PasswordAuthenticatorTest.java b/src/integration/java/com/couchbase/client/java/auth/PasswordAuthenticatorTest.java
new file mode 100644
index 0000000000000000000000000000000000000000..71e1ce0c67d0153986b4a65d54fb560cad9bdb17
