+
+package com.couchbase.client.java;
+
+import static org.junit.Assert.assertEquals;
+import static org.junit.Assert.assertTrue;
+
+
+import java.util.Collections;
+import java.util.List;
+
+import com.couchbase.client.core.CouchbaseException;
+import com.couchbase.client.java.cluster.ClusterManager;
+import com.couchbase.client.java.cluster.User;
+import com.couchbase.client.java.cluster.UserRole;
+import com.couchbase.client.java.cluster.UserSettings;
+import com.couchbase.client.java.util.CouchbaseTestContext;
+import com.couchbase.client.java.util.features.Version;
+import org.junit.AfterClass;
+import org.junit.BeforeClass;
+import org.junit.Test;
+import rx.Observable;
+import rx.functions.Func1;
+
+/**
+ * @author Subhashni Balakrishnan
+ */
+public class UserManagementTest {
+
+    private static CouchbaseTestContext ctx;
+    private static ClusterManager clusterManager;
+
+    private static final String USER_1 = "alice";
+    private static final String USER_2 = "bob";
+
+    @BeforeClass
+    public static void setup() {
+        ctx = CouchbaseTestContext.builder()
+                .build()
+                .ignoreIfClusterUnder(Version.parseVersion("5.0.0"));
+        clusterManager = ctx.clusterManager();
+    }
+
+    @AfterClass
+    public static void cleanup() {
+        ctx.destroyBucketAndDisconnect();
+    }
+
+    @Test
+    public void testUpsertUser() {
+        Observable
+                .just(USER_1)
+                .map(new Func1<String, UserSettings>() {
+                    @Override
+                    public UserSettings call(final String username) {
+                        return UserSettings
+                                .build()
+                                .name(username)
+                                .password("password")
+                                .roles(Collections.singletonList(new UserRole("data_reader", "*")));
+                    }
+                }).flatMap(new Func1<UserSettings, Observable<Boolean>>() {
+            @Override
+            public Observable<Boolean> call(final UserSettings userSettings) {
+                return clusterManager.async().upsertUser(userSettings.name(), userSettings);
+            }
+        }).toBlocking().single();
+        clusterManager.removeUser(USER_1);
+    }
+
+    @Test(expected = CouchbaseException.class)
+    public void testUpsertUserMissingPassword() {
+        Observable
+                .just(USER_2)
+                .map(new Func1<String, UserSettings>() {
+                    @Override
+                    public UserSettings call(final String username) {
+                        return UserSettings
+                                .build()
+                                .name(username)
+                                .roles(Collections.singletonList(new UserRole("data_reader", "*")));
+                    }
+                }).flatMap(new Func1<UserSettings, Observable<Boolean>>() {
+            @Override
+            public Observable<Boolean> call(final UserSettings userSettings) {
+                return clusterManager.async().upsertUser(userSettings.name(), userSettings);
+            }
+        }).toBlocking().single();
+    }
+
+    @Test
+    public void testGetUsers() {
+        Observable
+                .just("UserManagementTestUser1")
+                .map(new Func1<String, UserSettings>() {
+                    @Override
+                    public UserSettings call(final String username) {
+                        return UserSettings
+                                .build()
+                                .name(username)
+                                .password("password")
+                                .roles(Collections.singletonList(new UserRole("data_reader", "*")));
+                    }
+                }).flatMap(new Func1<UserSettings, Observable<Boolean>>() {
+            @Override
+            public Observable<Boolean> call(final UserSettings userSettings) {
+                return clusterManager.async().upsertUser(userSettings.name(), userSettings);
+            }
+        }).toBlocking().single();
+
+        Observable
+                .just("UserManagementTestUser2")
+                .map(new Func1<String, UserSettings>() {
+                    @Override
+                    public UserSettings call(final String username) {
+                        return UserSettings
+                                .build()
+                                .name(username)
+                                .password("password")
+                                .roles(Collections.singletonList(new UserRole("data_reader", "*")));
+                    }
+                }).flatMap(new Func1<UserSettings, Observable<Boolean>>() {
+            @Override
+            public Observable<Boolean> call(final UserSettings userSettings) {
+                return clusterManager.async().upsertUser(userSettings.name(), userSettings);
+            }
+        }).toBlocking().single();
+
+        List<User> users = clusterManager.async().getUsers().toList().toBlocking().single();
+        int matchCount = 0;
+        for (User user:users) {
+            if (user.userId().contains("UserManagementTest")){
+                matchCount += 1;
+            }
+        }
+        assertEquals("Get user list should contain users added", 2, matchCount);
+        clusterManager.removeUser("UserManagementTestUser1");
+        clusterManager.removeUser("UserManagementTestUser2");
+    }
+}
