+/**
+ * Rbac user in couchbase
+ *
+ * @author Subhashni Balakrishnan
+ * @since 2.4.4
+ */
+@InterfaceStability.Uncommitted
+@InterfaceAudience.Public
+public class User {
+    private String name;
+    private String userId;
+    private String type;
+    private UserRole[] roles;
+
+    protected void name(String name) {
+        this.name = name;
+    }
+
+    protected void userId(String userId) {
+        this.userId = userId;
+    }
+
+    protected void type(String type) {
+        this.type = type;
+    }
+
+    protected void roles(UserRole[] roles) {
+        this.roles = roles;
+    }
+
+    /**
+     * Get name of the user
+     * @return username
+     */
+    public String name() {
+        return this.name;
+    }
+
+    /**
+     * Get user id
+     * @return id
+     */
+    public String userId() {
+        return this.userId;
+    }
+
+    /**
+     * Get user type internal or ldap
+     * @return type
+     */
+    public String type() {
+        return this.type;
+    }
+
+    /**
+     * Get user roles
+     * @return roles array of user roles
+     */
+    public UserRole[] roles() {
+        return this.roles;
+    }
+}
