+
+    final String bucket;
+
+    public UserRole(String role) {
+        this.role = role;
+        this.bucket = "";
+    }
+
+    public UserRole(String role, String bucket) {
+        this.role = role;
+        this.bucket = bucket;
+    }
+
+    /**
+     * Get the role set
+     *
+     * @return role
+     */
+    public String role() {
+        return this.role;
+    }
+
