+    public String name() {
+        return this.name;
+    }
+
+    /**
+     * Get user id
+     * @return id
+     */
+    public String userId() {
+        return this.userId;
+    }
+
+    /**
+     * Get user type internal or ldap
+     * @return type
+     */
+    public String type() {
+        return this.type;
+    }
+
+    /**
+     * Get user roles
+     * @return roles array of user roles
+     */
+    public UserRole[] roles() {
+        return this.roles;
+    }
