diff --git a/src/main/java/com/couchbase/client/java/search/sort/SearchSort.java b/src/main/java/com/couchbase/client/java/search/sort/SearchSort.java
new file mode 100644
index 0000000000000000000000000000000000000000..a906918e14f6782916734a51e981860b8296b93c
--- /dev/null
