+            .put("query", JsonObject.create()
+                .put("min", "lower")
+                .put("inclusive_min", false)
+                .put("max", "upper")
+                .put("inclusive_max", true)
+                .put("boost", 1.5)
+                .put("field", "field"))
+            .put("explain", true);
+        assertEquals(expected, query.export());
+    }
+
+}
