diff --git a/src/main/java/com/couchbase/client/java/query/dsl/element/ExceptElement.java b/src/main/java/com/couchbase/client/java/query/dsl/element/ExceptElement.java
new file mode 100644
index 0000000000000000000000000000000000000000..3f68e6e43a551f0898fe5caf2f483f81d20afaa6
--- /dev/null
+++ b/src/main/java/com/couchbase/client/java/query/dsl/element/ExceptElement.java
@@ -0,0 +1,47 @@
+package com.couchbase.client.java.query.dsl.element;
+
+import com.couchbase.client.core.annotations.InterfaceAudience;
+import com.couchbase.client.core.annotations.InterfaceStability;
+import com.couchbase.client.deps.io.netty.util.internal.StringUtil;
+import com.couchbase.client.java.query.Statement;
+
+@InterfaceStability.Experimental
+@InterfaceAudience.Private
+public class ExceptElement implements Element {
+    private final boolean all;
+    private final String with;
+
+    public ExceptElement(final boolean all) {
+        this.all = all;
+        this.with = null;
+    }
+
+    public ExceptElement(final boolean all, final String with) {
+        this.all = all;
+        this.with = with;
+    }
+
+    public ExceptElement(final boolean all, final Statement with) {
+        this.all = all;
+        this.with = with.toString();
+    }
+
+    @Override
+    public String export() {
+        final StringBuilder sb = new StringBuilder();
+
+        sb.append("EXCEPT");
+
+        if (all) {
+            sb.append(" ALL");
+        }
+
+        if (!StringUtil.isNullOrEmpty(with)) {
+            sb.append(" ");
+            sb.append(with);
+        }
+
+        return sb.toString();
+
+    }
+}
