diff --git a/src/test/java/com/couchbase/client/java/search/queries/TermRangeQueryTest.java b/src/test/java/com/couchbase/client/java/search/queries/TermRangeQueryTest.java
new file mode 100644
index 0000000000000000000000000000000000000000..7d8270993a575eb149d1fab4864b15baa7ff9120
--- /dev/null
+++ b/src/test/java/com/couchbase/client/java/search/queries/TermRangeQueryTest.java
@@ -0,0 +1,101 @@
+/*
+ * Copyright (c) 2017 Couchbase, Inc.
+ *
+ * Licensed under the Apache License, Version 2.0 (the "License");
+ * you may not use this file except in compliance with the License.
+ * You may obtain a copy of the License at
+ *
+ *    http://www.apache.org/licenses/LICENSE-2.0
