new file mode 100644
index 0000000000000000000000000000000000000000..a31f0bcb92997474c9877b011df0ae5a390e2d83
--- /dev/null
+++ b/src/integration/java/com/couchbase/client/java/EphemeralBucketTest.java
@@ -0,0 +1,112 @@
+/*
