+        this.locationLat = locationLat;
+        this.distance = distance;
+    }
+
+    public GeoDistanceQuery field(String field) {
+        this.field = field;
+        return this;
+    }
+
+    @Override
+    public GeoDistanceQuery boost(double boost) {
+        super.boost(boost);
+        return this;
+    }
+
+    @Override
