diff --git a/src/main/java/com/couchbase/client/java/search/queries/TermRangeQuery.java b/src/main/java/com/couchbase/client/java/search/queries/TermRangeQuery.java
new file mode 100644
index 0000000000000000000000000000000000000000..ad4328063a40b7ca5ff2d2de7f614fa963e4af84
--- /dev/null
+++ b/src/main/java/com/couchbase/client/java/search/queries/TermRangeQuery.java
@@ -0,0 +1,115 @@
+/*
+ * Copyright (c) 2017 Couchbase, Inc.
+ *
+ * Licensed under the Apache License, Version 2.0 (the "License");
+ * you may not use this file except in compliance with the License.
+ * You may obtain a copy of the License at
