+package com.couchbase.client.java.search.queries;
+
+import com.couchbase.client.java.document.json.JsonArray;
+import com.couchbase.client.java.document.json.JsonObject;
+import org.junit.Test;
+
+import static org.junit.Assert.assertEquals;
+
+/**
+ * Verifies the functionality of {@link GeoDistanceQuery}.
+ *
+ * @author Michael Nitschinger
+ * @since 2.4.5
+ */
+public class GeoDistanceQueryTest {
+
+    @Test
+    public void shouldInjectRequiredParams() {
+        GeoDistanceQuery query = new GeoDistanceQuery(1.0, 2.0, "5m");
+        JsonObject result = JsonObject.create();
+        query.injectParams(result);
+
+        JsonObject expected = JsonObject.create()
+            .put("location", JsonArray.from(1.0, 2.0))
+            .put("distance", "5m");
+        assertEquals(expected, result);
+    }
+
+    @Test
+    public void shouldInjectField() {
+        GeoDistanceQuery query = new GeoDistanceQuery(1.0, 2.0, "5m");
+        query.field("fname");
+        JsonObject result = JsonObject.create();
+        query.injectParams(result);
+
+        JsonObject expected = JsonObject.create()
+            .put("location", JsonArray.from(1.0, 2.0))
+            .put("distance", "5m")
+            .put("field", "fname");
+        assertEquals(expected, result);
+    }
+}
diff --git a/src/test/java/com/couchbase/client/java/search/queries/TermRangeQueryTest.java b/src/test/java/com/couchbase/client/java/search/queries/TermRangeQueryTest.java
new file mode 100644
index 0000000000000000000000000000000000000000..7d8270993a575eb149d1fab4864b15baa7ff9120
--- /dev/null
+++ b/src/test/java/com/couchbase/client/java/search/queries/TermRangeQueryTest.java
@@ -0,0 +1,101 @@
+/*
+ * Copyright (c) 2017 Couchbase, Inc.
+ *
+ * Licensed under the Apache License, Version 2.0 (the "License");
+ * you may not use this file except in compliance with the License.
+ * You may obtain a copy of the License at
+ *
+ *    http://www.apache.org/licenses/LICENSE-2.0
+ *
+ * Unless required by applicable law or agreed to in writing, software
+ * distributed under the License is distributed on an "AS IS" BASIS,
+ * WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.
+ * See the License for the specific language governing permissions and
+ * limitations under the License.
+ */
+package com.couchbase.client.java.search.queries;
+
+import com.couchbase.client.java.document.json.JsonObject;
+import com.couchbase.client.java.search.SearchQuery;
+import org.junit.Test;
+
+import static com.googlecode.catchexception.CatchException.catchException;
+import static com.googlecode.catchexception.CatchException.caughtException;
+import static org.junit.Assert.assertEquals;
+import static org.junit.Assert.assertTrue;
+
+public class TermRangeQueryTest {
+
+    @Test
+    public void shouldFailIfNoBounds() {
+        TermRangeQuery fts = SearchQuery.termRange();
+        SearchQuery query = new SearchQuery("foo", fts);
+        catchException(query).export();
+
+        assertTrue(caughtException() instanceof NullPointerException);
+        assertTrue(caughtException().getMessage().contains("min or max"));
+    }
+
+    @Test
+    public void shouldAcceptMinOnly() {
+        TermRangeQuery fts = SearchQuery.termRange().min("lower");
+        SearchQuery query = new SearchQuery("foo", fts);
+        JsonObject expected = JsonObject.create()
+            .put("query", JsonObject.create()
+                .put("min", "lower"));
+        assertEquals(expected, query.export());
+    }
+
+    @Test
+    public void shouldAcceptMaxOnly() {
+        TermRangeQuery fts = SearchQuery.termRange().max("upper");
+        SearchQuery query = new SearchQuery("foo", fts);
+        JsonObject expected = JsonObject.create()
+            .put("query", JsonObject.create()
+                .put("max", "upper"));
+        assertEquals(expected, query.export());
+    }
+
+    @Test
+    public void shouldNotImplicitlySetDefaultsForInclusiveMinAndMax() {
+        TermRangeQuery fts = SearchQuery.termRange()
+            .boost(1.5)
+            .field("field")
+            .min("lower")
+            .max("upper");
+        SearchQuery query = new SearchQuery("foo", fts)
+            .explain();
+
+        JsonObject expected = JsonObject.create()
+            .put("query", JsonObject.create()
+                .put("min", "lower")
+                .put("max", "upper")
+                .put("boost", 1.5)
+                .put("field", "field"))
+            .put("explain", true);
+        assertEquals(expected, query.export());
+    }
+
+    @Test
+    public void shouldExportDateRangeQueryWithAllOptions() {
+        TermRangeQuery fts = SearchQuery.termRange()
+            .boost(1.5)
+            .field("field")
+            .min("lower", false)
+            .max("upper", true);
+        SearchQuery query = new SearchQuery("foo", fts)
+            .explain();
+
+        JsonObject expected = JsonObject.create()
+            .put("query", JsonObject.create()
+                .put("min", "lower")
+                .put("inclusive_min", false)
+                .put("max", "upper")
+                .put("inclusive_max", true)
+                .put("boost", 1.5)
+                .put("field", "field"))
+            .put("explain", true);
+        assertEquals(expected, query.export());
+    }
+
+}
