+        String key = "createDocumentInSubdocCounter";
+        removeIfExists(key);
+        DocumentFragment<Mutation> response = ctx.bucket().mutateIn(key)
+                .counter("counter", 1)
+                .createDocument(true)
+                .execute();
+        assertTrue(response.status(0) == ResponseStatus.SUCCESS);
+        ctx.bucket().remove(key);
+    }
 }

