new file mode 100644
index 0000000000000000000000000000000000000000..9e9e364a92a28703d4792a4b7c1b85be7c9a3b33
--- /dev/null
+++ b/src/main/java/com/couchbase/client/java/util/TransparentReplicaGetHelper.java
@@ -0,0 +1,163 @@
+/**
