diff --git a/src/integration/java/com/couchbase/client/java/transcoder/CustomTranscoderTest.java b/src/integration/java/com/couchbase/client/java/transcoder/CustomTranscoderTest.java
new file mode 100644
index 0000000000000000000000000000000000000000..c4abb759e4cf72cf8c5b716d57d65ea0255a5158
--- /dev/null
+++ b/src/integration/java/com/couchbase/client/java/transcoder/CustomTranscoderTest.java
@@ -0,0 +1,186 @@
+/*
+ * Copyright (c) 2017 Couchbase, Inc.
+ *
+ * Licensed under the Apache License, Version 2.0 (the "License");
+ * you may not use this file except in compliance with the License.
+ * You may obtain a copy of the License at
+ *
+ *    http://www.apache.org/licenses/LICENSE-2.0
