new file mode 100644
index 0000000000000000000000000000000000000000..79d25343cec8bebc1a0ecad524dd253e10e307b9
--- /dev/null
+++ b/src/main/java/com/couchbase/client/java/document/ByteArrayDocument.java
@@ -0,0 +1,161 @@
+/*
