+ * WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.
+ * See the License for the specific language governing permissions and
+ * limitations under the License.
+ */
+package com.couchbase.client.java.document;
+
+import com.couchbase.client.core.message.kv.MutationToken;
+
+import java.io.IOException;
+import java.io.ObjectInputStream;
+import java.io.ObjectOutputStream;
+import java.io.Serializable;
+
+/**
+ * Handles a raw string as the document value.
+ *
+ * This document differs from {@link BinaryDocument} in that there is no manual refcounting needed on the
+ * underlying buffers. As a result, it is much safer to work with than the traditional {@link BinaryDocument}
+ * and should be preferred as a result. Note that the cost is a single byte array copy from the buffer, so if this
+ * is still too much then the {@link BinaryDocument} should be used as a last resort.
+ *
+ * @author Michael Nitschinger
+ * @since 2.5.2
+ */
+public class ByteArrayDocument extends AbstractDocument<byte[]> implements Serializable {
+
+    private static final long serialVersionUID = -8616443474645912439L;
+
+    /**
+     * Creates a {@link ByteArrayDocument} which the document id.
+     *
+     * @param id the per-bucket unique document id.
+     * @return a {@link ByteArrayDocument}.
+     */
+    public static ByteArrayDocument create(String id) {
+        return new ByteArrayDocument(id, 0, null, 0, null);
+    }
+
+    /**
+     * Creates a {@link ByteArrayDocument} which the document id and content.
+     *
+     * @param id the per-bucket unique document id.
+     * @param content the content of the document.
+     * @return a {@link ByteArrayDocument}.
+     */
+    public static ByteArrayDocument create(String id, byte[] content) {
+        return new ByteArrayDocument(id, 0, content, 0, null);
+    }
+
+    /**
+     * Creates a {@link ByteArrayDocument} which the document id, content and the CAS value.
+     *
+     * @param id the per-bucket unique document id.
+     * @param content the content of the document.
+     * @param cas the CAS (compare and swap) value for optimistic concurrency.
+     * @return a {@link ByteArrayDocument}.
+     */
+    public static ByteArrayDocument create(String id, byte[] content, long cas) {
+        return new ByteArrayDocument(id, 0, content, cas, null);
+    }
+
+    /**
+     * Creates a {@link ByteArrayDocument} which the document id, content and the expiration time.
+     *
+     * @param id the per-bucket unique document id.
+     * @param content the content of the document.
+     * @param expiry the expiration time of the document.
+     * @return a {@link ByteArrayDocument}.
+     */
+    public static ByteArrayDocument create(String id, int expiry, byte[] content) {
+        return new ByteArrayDocument(id, expiry, content, 0, null);
+    }
+
+    /**
+     * Creates a {@link ByteArrayDocument} which the document id, content, CAS value, expiration time and status code.
+     *
+     * This factory method is normally only called within the client library when a response is analyzed and a document
+     * is returned which is enriched with the status code. It does not make sense to pre populate the status field from
+     * the user level code.
+     *
+     * @param id the per-bucket unique document id.
+     * @param content the content of the document.
+     * @param cas the CAS (compare and swap) value for optimistic concurrency.
+     * @param expiry the expiration time of the document.
+     * @return a {@link ByteArrayDocument}.
+     */
+    public static ByteArrayDocument create(String id, int expiry, byte[] content, long cas) {
+        return new ByteArrayDocument(id, expiry, content, cas, null);
+    }
+
+    /**
+     * Creates a {@link ByteArrayDocument} which the document id, content, CAS value, expiration time and status code.
+     *
+     * This factory method is normally only called within the client library when a response is analyzed and a document
+     * is returned which is enriched with the status code. It does not make sense to pre populate the status field from
+     * the user level code.
+     *
+     * @param id the per-bucket unique document id.
+     * @param content the content of the document.
+     * @param cas the CAS (compare and swap) value for optimistic concurrency.
+     * @param expiry the expiration time of the document.
+     * @return a {@link ByteArrayDocument}.
+     */
+    public static ByteArrayDocument create(String id, int expiry, byte[] content, long cas, MutationToken mutationToken) {
+        return new ByteArrayDocument(id, expiry, content, cas, mutationToken);
+    }
+
+    /**
+     * Creates a copy from a different {@link ByteArrayDocument}, but changes the document ID and content.
+     *
+     * @param doc the original {@link ByteArrayDocument} to copy.
+     * @param id the per-bucket unique document id.
+     * @param content the content of the document.
+     * @return a copied {@link ByteArrayDocument} with the changed properties.
+     */
+    public static ByteArrayDocument from(ByteArrayDocument doc, String id, byte[] content) {
+        return ByteArrayDocument.create(id, doc.expiry(), content, doc.cas(), doc.mutationToken());
+    }
+
+    /**
+     * Creates a copy from a different {@link ByteArrayDocument}, but changes the CAS value.
+     *
+     * @param doc the original {@link ByteArrayDocument} to copy.
+     * @param cas the CAS (compare and swap) value for optimistic concurrency.
+     * @return a copied {@link ByteArrayDocument} with the changed properties.
+     */
+    public static ByteArrayDocument from(ByteArrayDocument doc, long cas) {
+        return ByteArrayDocument.create(doc.id(), doc.expiry(), doc.content(), cas, doc.mutationToken());
+    }
+
+    /**
+     * Private constructor which is called by the static factory methods eventually.
+     *
+     * @param id the per-bucket unique document id.
+     * @param content the content of the document.
+     * @param cas the CAS (compare and swap) value for optimistic concurrency.
+     * @param expiry the expiration time of the document.
+     */
+    private ByteArrayDocument(String id, int expiry, byte[] content, long cas, MutationToken mutationToken) {
+        super(id, expiry, content, cas, mutationToken);
+    }
+
+    private void writeObject(ObjectOutputStream stream) throws IOException {
+        writeToSerializedStream(stream);
+    }
+
+    private void readObject(ObjectInputStream stream) throws IOException, ClassNotFoundException {
+        readFromSerializedStream(stream);
+    }
+}
diff --git a/src/main/java/com/couchbase/client/java/transcoder/ByteArrayTranscoder.java b/src/main/java/com/couchbase/client/java/transcoder/ByteArrayTranscoder.java
new file mode 100644
index 0000000000000000000000000000000000000000..31308cd685e6b6391609d32553a940042514d11f
--- /dev/null
+++ b/src/main/java/com/couchbase/client/java/transcoder/ByteArrayTranscoder.java
@@ -0,0 +1,74 @@
+/*
+ * Copyright (c) 2017 Couchbase, Inc.
+ *
+ * Licensed under the Apache License, Version 2.0 (the "License");
+ * you may not use this file except in compliance with the License.
+ * You may obtain a copy of the License at
+ *
+ *    http://www.apache.org/licenses/LICENSE-2.0
+ *
+ * Unless required by applicable law or agreed to in writing, software
+ * distributed under the License is distributed on an "AS IS" BASIS,
+ * WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.
+ * See the License for the specific language governing permissions and
+ * limitations under the License.
+ */
+package com.couchbase.client.java.transcoder;
+
+import com.couchbase.client.core.lang.Tuple;
+import com.couchbase.client.core.lang.Tuple2;
+import com.couchbase.client.core.message.ResponseStatus;
+import com.couchbase.client.core.message.kv.MutationToken;
+import com.couchbase.client.deps.io.netty.buffer.ByteBuf;
+import com.couchbase.client.deps.io.netty.buffer.Unpooled;
+import com.couchbase.client.java.document.ByteArrayDocument;
+import com.couchbase.client.java.error.TranscodingException;
+
+/**
+ * A transcoder to encode and decode {@link ByteArrayDocument}s.
+ *
+ * This transcoder makes it much easier to work with raw binary data than {@link BinaryTranscoder} since
+ * on retry and unsubscribe, buffers don't need to be freed and managed seperately. As a result, for all
+ * but special purpose cases it should be preferred over {@link BinaryTranscoder}.
+ *
+ * @author Michael Nitschinger
+ * @since 2.5.2
+ */
+public class ByteArrayTranscoder extends AbstractTranscoder<ByteArrayDocument, byte[]> {
+
+    @Override
+    protected ByteArrayDocument doDecode(String id, ByteBuf content, long cas, int expiry, int flags,
+        ResponseStatus status) throws Exception {
+        if (!TranscoderUtils.hasBinaryFlags(flags)) {
+            throw new TranscodingException("Flags (0x" + Integer.toHexString(flags) + ") indicate non-binary " +
+                "document for id " + id + ", could not decode.");
+        }
+        byte[] data = new byte[content.readableBytes()];
+        content.readBytes(data);
+        return newDocument(id, expiry, data, cas);
+    }
+
+    @Override
+    protected Tuple2<ByteBuf, Integer> doEncode(ByteArrayDocument document) throws Exception {
+        return Tuple.create(
+            Unpooled.wrappedBuffer(document.content()),
+            TranscoderUtils.BINARY_COMPAT_FLAGS
+        );
+    }
+
+    @Override
+    public ByteArrayDocument newDocument(String id, int expiry, byte[] content, long cas) {
+        return ByteArrayDocument.create(id, expiry, content, cas);
+    }
+
+    @Override
+    public ByteArrayDocument newDocument(String id, int expiry, byte[] content, long cas,
+        MutationToken mutationToken) {
+        return ByteArrayDocument.create(id, expiry, content, cas, mutationToken);
+    }
+
+    @Override
+    public Class<ByteArrayDocument> documentType() {
+        return ByteArrayDocument.class;
+    }
+}
diff --git a/src/test/java/com/couchbase/client/java/transcoder/ByteArrayTranscoderTest.java b/src/test/java/com/couchbase/client/java/transcoder/ByteArrayTranscoderTest.java
new file mode 100644
index 0000000000000000000000000000000000000000..edeb2c11767ccd044afc464395a00be65215d9db
--- /dev/null
+++ b/src/test/java/com/couchbase/client/java/transcoder/ByteArrayTranscoderTest.java
@@ -0,0 +1,63 @@
+/*
+ * Copyright (c) 2017 Couchbase, Inc.
+ *
+ * Licensed under the Apache License, Version 2.0 (the "License");
+ * you may not use this file except in compliance with the License.
+ * You may obtain a copy of the License at
+ *
+ *    http://www.apache.org/licenses/LICENSE-2.0
+ *
+ * Unless required by applicable law or agreed to in writing, software
+ * distributed under the License is distributed on an "AS IS" BASIS,
+ * WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.
+ * See the License for the specific language governing permissions and
+ * limitations under the License.
+ */
+package com.couchbase.client.java.transcoder;
+
+import com.couchbase.client.core.lang.Tuple2;
+import com.couchbase.client.core.message.ResponseStatus;
+import com.couchbase.client.deps.io.netty.buffer.ByteBuf;
+import com.couchbase.client.deps.io.netty.buffer.Unpooled;
+import com.couchbase.client.deps.io.netty.util.CharsetUtil;
+import com.couchbase.client.java.document.ByteArrayDocument;
+import org.junit.Before;
+import org.junit.Test;
+
+import static org.junit.Assert.assertEquals;
+
+/**
+ * Verifies the functionality of the {@link ByteArrayTranscoder}.
+ *
+ * @author Michael Nitschinger
+ * @since 2.5.2
+ */
+public class ByteArrayTranscoderTest {
+
+    private ByteArrayTranscoder converter;
+
+    @Before
+    public void setup() {
+        converter = new ByteArrayTranscoder();
+    }
+
+    @Test
+    public void shouldEncodeFromByteArray() {
+        ByteArrayDocument document = ByteArrayDocument.create("id", "value".getBytes(CharsetUtil.UTF_8));
+        Tuple2<ByteBuf, Integer> encoded = converter.encode(document);
+
+        assertEquals("value", encoded.value1().toString(CharsetUtil.UTF_8));
+        assertEquals(TranscoderUtils.BINARY_COMPAT_FLAGS, (long) encoded.value2());
+    }
+
+    @Test
+    public void shouldDecodeIntoByteArray() {
+        ByteBuf content = Unpooled.copiedBuffer("value", CharsetUtil.UTF_8);
+        ByteArrayDocument decoded = converter.decode("id", content, 0, 0,
+            TranscoderUtils.BINARY_COMMON_FLAGS, ResponseStatus.SUCCESS);
+
+        assertEquals("value", new String(decoded.content(), CharsetUtil.UTF_8));
+        assertEquals(0, content.refCnt());
+    }
+
+}

